/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20071127-8","meetingId":"h19-cm11","date":"2007年11月27日","dateIso":"2007-11-27","committee":"建設委員会","time":"午前１０時０２分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"品川区立公園条例施行規則の一部改正","agenda":"品川区立公園条例施行規則の一部改正","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そう考えると、天王洲公園はちょっと周りに住んでいらっしゃる方もいらっしゃるから難しいのかなとちょっと思うけれども、八潮北公園なんかは大丈夫なんじゃないのかなと思うんだけれども、そういうことを考えると、八潮北公園も、ここでそのまま午後９時に据え置いているんだけれども、午後１１時なんていうことは考えられていないのかなと、あわせてお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"今回実施する中でいろいろなデータを集めていきたいと考えているということと、９時以降の話は、フットサルとかはほかの施設でも結構使われているという形がありますので、そういった面では。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、なおかつ少しどんどん足していって、ある程度平らにしないと逆に危険だということもあって、あのやわらかさが果たしていいのかというのはよく皆さんも言うんですけれども、それはぜひ今度、多分同じような形になると思うので、それは天王洲公園も含めて、管理をされるところに、せっかく天王洲公園なんかはローラーもあるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"使用料について考え方をお伺いしたいんですけれども、品川南ふ頭公園のほうは、野球場として使用する場合、区内チームが２時間１,５００円、区外チームは３,０００円とありますけれども、どのように算出されたのか、計算の根拠をもうちょっとご説明いただきたいということと、あと管理に対してですけれども、どこかに委託の考えがあるのか、先ほど管理の形は人的管理という話がありましたけれども。","respondent":"藤田道路公園課長","answer":"使用料金の関係ですけれども、一般的に私どもの施設を管理する中では、管理するためのコストの何割かを区民の皆さんにご負担いただくという形で、受益者負担という考え方を原則としておりまして、今回は使用料についても改正を特にするわけではないので。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ということは、この１,５００円なり３,０００円の考え方は、管理をするためのコストの何割かという考えで算出されたものなのか、もう一度確認させていただきたいのと、あと委託ということですけれども、そうなると、年間の委託料がどれぐらいを見込んでいるのか、また使用料収入はどれぐらいを見込んでいるのか、教えていただけますか。","respondent":"藤田道路公園課長","answer":"おおむねかかっているコストの３割程度が、使用料でご負担をいただいているものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"管理のためのコストの３割程度を受益者負担で利用者に負担してもらうということなんですけれども、何で３割なのか、この３割の根拠、これはよくわからないんですね。ということは、きちんと区のほうでその３割分の利用料を補てんすれば無料にすることもできるわけですよね。３割の根拠は何なのか教えていただきたいんですが。","respondent":"岩田まちづくり事業部長","answer":"したがって、近いうちには使用料の変更というものも考えざるを得ませんが、今年度は改定はしないということで、このまま同一料金でいきたいです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"その中で他区との比較で、全部の区を私もまだ調べているわけではないですけれども、コインロッカーの１０円についていろいろな意見をよく伺うんですね。ほかの施設で１０円入れて、終わると返ってくるというんですよ。何区か、調べたんだけれども、ごめんなさい。使って、終わったら出てくる、この仕組みを考えるべきではないのかなと思うんですけれども、最後にコインロッカーについてはいかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"ちょっと大きめのところですと２００円とか３００円になるわけですけれども、１０円でずっと据え置いているわけですから、これはいたずら防止も含めて、最低金額でありますけれども、１０円をご負担をしていただくということでご理解をぜひお願いしたいと思います。","id":"exchange-006"},{"speaker":"井上委員","kind":"意見","question":"八潮北公園の庭球場のほうなんですけれども、庭球場を拡大するという判断をされた理由と、それによって、ほかのところで野球場でやっているのであまり変わらないかもしれないんですけれども、管理費みたいなもので費用がかかるということがあるのであれば、どのくらいになるのか。","respondent":"藤田道路公園課長","answer":"八潮北公園のテニスコートの関係ですけれども、この４月に野球場の早朝の土日、休日オープンしたときに、テニスコートについてもできるんじゃないかということで、ただテニスコートの早朝利用って、区の中でまだ１カ所もやっていないので、利用実態がどのくらいあるのか。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと漠然としていてわからなかったので、そこを教えていただきたいことと、あと場所的にここができるというのがあるんですけれども、今後の展望として、ほかにもテニスコートがあるわけですけれども、ここが初めての拡大というところで、その辺はどんなふうに、してほしいとか、しないでほしいとかいうことを思っているわけではないんですけれども、区の展望として。","respondent":"藤田道路公園課長","answer":"野球に限らずテニスもそうだと思いますけれども、平日の早朝利用なんかも、もしご利用したい方がいっぱいいれば、それは考えていかなきゃいけないかなと考えていますが、なかなか利用実態と合わせると、そうはいかないのが実態でございまして、今後も利用者の意見を聞きながら。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"さっきの品川南ふ頭公園のほうの委託するところはもう決まったんでしょうか。","respondent":"藤田道路公園課長","answer":"委託については年間契約で考えておりますので、まだまだこれから業者の選定に入るということになります。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"いろいろあるとは思いますが、ざっくりお願いします。それともう１点なんですけれども、区のかかわるスポーツ施設の利用時間なんですけれども、これは夜９時から１１時とか、例えば近隣に住宅地があるとかないとか、そういったことで夜９時ぐらいまでの使用とか、１１時ぐらいまでオーケーとか、そういう基準、考え方みたいなものはあるんでしょうか。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"今回初めて周辺の環境を勘案して、１１時まで品川南ふ頭公園については貸し出しができるだろうという判断の中で拡大したです。もちろんこれは利用者あっての実態に変えていく内容ですから、利用者がだれなのか、その辺はよくこれから教育委員会、スポーツ協会等々と、いろいろと実態をつかんで、それに対応して。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"確かにニーズがあり、そして近隣に対する迷惑もないということであれば、枠の拡大というのも１つの方向かなと思うんですが、一方で、ちょっと公園から外れてしまうんですけれども、そういうものとかかわるといったらいいんでしょうかね、住宅地の中にあるフットサル場を夜１１時まで営業していて、大変に近所の方から苦情も多いと聞いていますが、そういったところの時間を短くするような判断というのは。","respondent":"岩田まちづくり事業部長","answer":"あの施設につきましては、区の普通財産として貸し付けているところで、当然当初からその時間帯まで営業をして利益を上げられるということでおそらく借りた施設でしょうから、今の段階でそれを短くするということが、区から言えないことはないでしょうけれども。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、事業者の判断で、例えば今、１１時ですけれども、それが２時、３時まで営業が成り立つとなれば、それはやっちゃっても、区は何とも言えませんよということですか。区の関連施設を管理するときには、周辺の状況も考えてやるということでありながら、区の施設を貸し付けるときには、住民の生活について考えなくていいというのはおかしいんじゃないかということだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"仮にサッカー人口のほうが該当者が野球の半分と見積もっても、年間１２カ月あれば最低４カ月ぐらいは、私は区民サービスを考えるにあたって、野球の今までやってきた慣習もわかりますが、やはりそこは平等という観点から、アンバランスというのを取り除いて、一歩野球のほうにも話し合いで譲っていただいて、１２月から３月ぐらいまではサッカーを優先にするとか。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"ただこの間、どうしても青空野球場のＡ・Ｂ・Ｃ面まですべてなくなってしまうという背景を考えると、ある程度野球への配慮もするということで、今後利用者の実態がどう変わっていくか、それからなかなか場所がありませんけれども。もちろん、今後、利用実態に合わせてきちんと対応していく予定ですけれども、今のところこのような実態ですので、まずはこのようなことをきちんと踏まえて利用していただくというのが基本だろうと考えています。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただやはり１５年たって、それぞれ愛好者が増えてきた中で、片一方に関してはかなり大幅な優先期間を設けて、同じ場所で、片一方は少ないということは、区全体でとらえられたときに、よい施策をやっている中で、悪いような見方もされることもあると思いますので、１５年たった中で、今後いい方向で、ただ今回規定されちゃったわけで、変えていくということなので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"「目黒川右岸低地部排水施設整備工事その３」の着手","agenda":"「目黒川右岸低地部排水施設整備工事その３」の着手","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"９０度ぐらい曲がるところが２カ所ありますよね。これはもちろんそれより浅いわけだけれども、１つは民地に入らない考え方と、こういう場合の大深度をどう使っていくかという考えが、今後そういうことを考えるのであればあると思うんだけれども、その考え方を両方教えてもらえればと思います。","respondent":"家壽田下水道河川課長","answer":"２点のご質問にお答えいたします。民地に入るか入らないかですと、基本的には下水道管は道路の下を占用するという考えです。ただやむを得ず民地を占用する場合がございまして、その際には当然権利を侵すわけですので、地上権設定等のコストがかかると思います。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"昨日の説明で、これが完成すると、いわゆる５０mmの雨で対応の範囲が広がる、充実できるという話ですけれども、最近の雨は５０mmの雨というよりも、２０分、３０分で瞬間的に、そこだけ見ると１００mmぐらいの雨がどどっと降って、川に流れ込んで、その上、品川区は海に近いですから、ここではそんなに降っていない気分でも、上流のほうで降っていると思いのほか川に流れ込む量が増える。","respondent":"家壽田下水道河川課長","answer":"ただやはりそういった１００mmの雨が降っているという自治体もありますので、今年に入りまして、東京都は豪雨対策基本方針という方針を定めておりまして、その中でもそういった１００mm対策について、今後都としてどうやっていくかということも示されておりますので。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"今いろいろ検討されているというお話でしたけれども、どういうふうに対策が考えられるのか、何か具体的な方法とか、新しいアイデアといいますか、そういうのがもしあるんだったら、ちょっと教えていただけますか。","respondent":"家壽田下水道河川課長","answer":"ためるという意味では、総合的な治水対策と呼んでいますけれども、降った雨が下水道管や、川に流れてこなければいいわけでして、それを例えば雨水のタンクに入れてあげるとか、雨水を浸透させるということ、これも大変効果的なものですので。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"東京都とかではこういう工事にあたっては、談合の問題があったりとかというときには工事を停止するということで決めているそうですけれども、品川区は今後そういうときにどう対応していくかということも課題になるかと思うんですけれども、その辺をこれからの取り組みとして考えていらっしゃるところがあるのかどうかということ、そういうことも必要な時代になっているのかなと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"今、その２工事をされているということだと思うんですけれども、その２工事自体はいつごろまでかかるかということと、その３工事については書いてありますけれども、ここにある推進工（計画）というのは、これはいつごろ行われるのかということと、全体ができ上がった後で、下水道管として使われるのか、いつごろからこれが利用されることになるのかということについて教えてください。","respondent":"家壽田下水道河川課長","answer":"ただし先ほど、私ご説明いたしましたこの接続先が鮫洲ポンプ所を通って、勝島ポンプ所と申し上げましたが、この勝島ポンプ所の完成がまだ平成２１年度には終わっておりませんので、その段階では暫定的に雨水をためるということで対応しておりまして。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"ちょっと技術的なことに弱いものですから、ポンプ所ができなくて、下水管だけできて、上流のほうからもいっぱい水が流れてきたら、水をためるどころかあふれちゃうんじゃないかという気がしたんですけれども、その辺はどうなっているんですか。","respondent":"家壽田下水道河川課長","answer":"今回の暫定的にためるという話は、降った雨を全部ため込むんじゃなくて、暫定貯留するという考え方がございまして、あふれそうになる部分の水をため込むと。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"先ほど話が出ましたが、民地権についてお聞かせ願いたいんですが、やむを得ず通る場合もあるわけですよね。そのときにそこの方が、将来はわからないんですが、かなり地下何十階という形で使うんだと。十何階なんですかね。そのときに返してほしい。でも貯留管というか、こういう円形管はもうできているわけなんですが、そういうときはどういうふうになるんですか。","respondent":"家壽田下水道河川課長","answer":"あくまでも民間の下を通するということは、所有権を設定いたしますので、それは権利として買わせていただきますので、それは買った以上は使わせていただくです。","id":"exchange-021"},{"speaker":"須貝委員","kind":"意見","question":"ちょっともったいないんじゃないかと。今後こういう集中豪雨、スコール的な雨というのはますます増える中で、今回このような径を設定をしたわけですが、どういうことで３ｍ、仕上がり内径で２.６ｍですが、その辺のご見解をお聞かせください。","respondent":"家壽田下水道河川課長","answer":"そういったことも総合的に勘案しまして、今回は２,６００mm径を選定しているものです。","id":"exchange-022"},{"speaker":"須貝委員","kind":"意見","question":"よくわかりました。せっかく地下を掘っていって、あれだけの工事をしていて、これを将来またでかくするというのはまず不可能だと思うし、５０mmという設定で予算組みされるとは思うんですが、やはり前もってもっと余裕を持った、将来に向けた大きさを都のほうにお願いをしていただければありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"三上委員","kind":"質問","question":"今の話の関連で、不動前の幹線をつくったじゃないですか。あのとき一時貯留するということで、不動前は水が出なくなったということがあるので、少しそこらあたりの話をしてみてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"三上委員","kind":"意見","question":"要するに不動前あたりの一時貯留で、今のような現実に掘っているところを完全にふたをしちゃって、それで一時貯留という形で使えるようにしたわけでしょう。そういうことをやるようになってから出なくなったということでしょう。そういう話をしてあげないと、先ほども一時貯留させるという話をしているわけだから、そういう効果があるんだということを話してくださいと言ったわけです。","respondent":"家壽田下水道河川課長","answer":"それはシミュレーションの結果でもそういったものを、貯留するとどれだけ効果があるかというのも最近の技術で明らかになっています。今回、先ほどご説明しましたが、本来であれば、勝島ポンプ所ができるまでは、動かさないというのが下水道管理の前提です。","id":"exchange-025"}]},{"id":"topic-03","title":"都営住宅（地元割当）入居者募集","agenda":"都営住宅（地元割当）入居者募集","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"関連して、この前の本会議でも、早い話が１万５,０００の空き部屋があるから、公営住宅を今後つくる環境じゃないという話もよくされるわけですけれども、民間ストックの活用とこの間言ってきましたけれど、それはどういう内容なのかちょっとご説明いただきたいのと、あと１万５,０００の部屋といいますけれども、私が言いたいのは、都営住宅の家賃に比べれば高いだろうなと思っているんですけれども。","respondent":"齋藤住宅課長","answer":"ストックの話ですが、今、世帯数が品川区内に１７万４,０００ぐらい世帯がありまして、直近の総務省の住宅・土地統計調査によりますと、区内には２０万戸を超える住宅数となっております。差し引きすると２万以上あきがある。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"聞き方が間違っていたんですけれども、今、２万の部屋があいていると。だから公営住宅をつくる環境にないという話で、この２万のあいている部屋というのは、どういう家賃なのか、都営住宅に入居を申し込んだ方々の収入で可能な規模なのかどうか、そこを教えていただきたい。","respondent":"齋藤住宅課長","answer":"総務省の統計でありますので、２万戸がどのような状況や家賃相場で借りに出されているのか、なぜ借り手がないのか、こういったものについては詳細は承知しておりません。","id":"exchange-027"}]},{"id":"topic-04","title":"の所管質問","agenda":"の所管質問","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"何年かかけてこの広町のＪＲの方たちと協議をしてきたという、一般質問の中のいろいろな答弁もありまして、その中で今回、今のところ計画がその先に進むということではないということもわかったわけですけれども、そのときに、昨日もちょっと言いましたけれども、Ｃ地区という今日いただいた資料にもありますけれども、そういったところで道路整備が必要であるとか。","respondent":"青木都市開発課長","answer":"なおかつゼームス坂の三叉路あたりでは渋滞が慢性化しているということを考えますと、大井町駅の周辺、まちづくりを進めていく上では、東西方向の道路基盤が脆弱であるという視点から、この広町の開発に合わせて、せめて補助１６３号線は今後拡幅整備を予定していますので。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"このようなデータがあるということがやっぱり広く、これによってどういう影響とかがあるというところはよくわかりませんけれども、しっかりとこのような取り組みをされてきたということが、どこかで出てくるのか、出すべきだと思います。それはうまくいってほしいなと思うんですけれども、そういうときはどういう考え方のもとに情報提供などをされるんでしょうか。","respondent":"青木都市開発課長","answer":"これがいくら何でも昭和５６年から全く新しい構想もなく、品川区がそのまま昔ながらのことをやるんですかということでは申しわけないという考え方もありまして、大井プレイス構想とは違う広町を位置づけた中で。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"すごく変なことを聞いていいですか。しかしながら、先ほど来、１０年から２０年後を考えて、区の顔としてということで考えると、私もそういうふうに今まで思っていたんだけれども、品川区の顔というのは、大井町周辺なのかというのをもう一度見つめ直す時期に来たと思っているんだけれども、大井町周辺を顔として位置づけるのかどうかということについて、どう思われているのかを、もし答えられるなら。","respondent":"岩田まちづくり事業部長","answer":"ただ顔だから、ほかのところよりはここを重点的にという意味合いではなくて、武蔵小山しかり、天王洲地区しかり、目黒駅しかり、いわゆる各地区ごとに品川区とすれば、大井町ほどの大きさではございませんけれども。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"意見","question":"どうしてそんなことを言ったかといいますと、品川区の考え方を踏まえて言っているんですが、東京都でも例えば今後の１０年間の計画を出しているとか、いろいろ出てくると、どうしても山手通りの内側という考えが非常に出てきているように思います。それで、山手通りの内側というと大井町は入らない。ああいうまちに変わった。そうなると、そこを主に置くのか。","respondent":"岩田まちづくり事業部長","answer":"ただ五反田駅は区画整理がある程度進んでおりますので、インフラについてはほぼ十分な状態になっておりますが、ＴＯＣの建替計画もありますし、乗降客数ではダントツに多いんですけれども、その乗降客が五反田駅でおりてお金を落とすような仕組みづくりというのは。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうことを考えると、ここの地区のインフラということを考えると、先ほども言ったように、ＪＲもどこに主眼を置いているかというと、ＪＲは東京都全体のことを考えていらっしゃるんでしょうから、山手通り内側と考えられているのか、そうなってくると、今度京浜急行も乗るという話が新聞紙上でも出ると、どうしてもあの沿線沿いは京急が持っている土地がほとんどであるわけですから、そうすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"この資料についてなんですけれども、先ほどの説明の中でも触れられていましたけれども、導入機能（市場調査からの割り出し）とありましたけれども、この市場調査というのは、いつ、どこの調査なのか、それを教えていただきたいなと思います。話の流れの中で言うと、ＪＲと品川区との共同研究、コンサルタントの話を含め共同研究の中で出てきたものなのかどうか、教えていただけますか。","respondent":"青木都市開発課長","answer":"ですので、最後に結論保留と書いてありますとおり、それはそれとして、ＪＲも聞いたし、区も聞いたけれども、それは結論ではないということで、勉強したという形でのデータです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"広町地区開発について、ＪＲと品川区の協議の内容がなかなか見えてこないんですね。なぜかというと、冒頭の話の中で、テーマパークも調査を依頼したというので、何で急にテーマパークになったのかよくわからないんですよね。そのデータの中でテーマパークはだめになったのかもしれないけれども、なぜテーマパークなんて依頼したんですか。","respondent":"青木都市開発課長","answer":"テーマパークについての検討というご質問、なぜテーマパークの検討を依頼したのかという点ですけれども、既存の商店街がそこそこ今頑張っていらっしゃる、商業集積があるという現実から、その商業集積をつぶすことなく、繁栄を共存できるような施設は何かということで考える中で。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"調査のデータを見せていただきたいということで、調査というのは客観的なものですよね。ＪＲの電車のつくり方かどうかわかりませんけれども、そこを言っているんじゃなくて、どういう民間のリサーチ会社か、どういう調査をしたのかわからないけれども、ぜひそれは出していただきたい。それとテーマパークという関係がよくわからないんですけれども、これは何をイメージされていたのか。","respondent":"岩田まちづくり事業部長","answer":"したがって、ＪＲからいただいている図面関係も、かなり修正をしないと表に出せない部分が多々ありますので、文章表現も含めて、どこまで皆さんにオープンにできるものか、あるいは資料編として、非公開にはなりますけれども、検討結果を後々検証できるようなものとして。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問・要望","question":"その検討結果なんですけれども、株式会社丸井があったことを前提にした内容ということになっていて、一応その商業の集積ができていて、各品目がそろうということがまさに前提になっているわけですけれど、既にその状況が変わってきてしまっているということ、それからさらに言わせてもらえば、本当に大井町は商業の集積地なのかというのは大変疑問がございまして、確かに商店街は頑張っていますし。","respondent":"岩田まちづくり事業部長","answer":"ですから、あまり行政が深入りはできない分野のことなんですけれども、ただこのＪＲの敷地はあまりにも巨大ですので、そういう面ではここはかなりフリーにいろいろなことが考えられるということで、ＪＲもいろいろな可能性があるならばということで検討したので。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"それだけ大規模な面的な部分があるわけです。そういうことから、もう少し全体的な考え方ということで取り組むということを考えていくべきではないかなと、これは私の感想なんですけれども、そこらあたりについてのご意見を、そういう考え方もあるんだなというふうに受けとめていくのかどうか、ちょっとお伺いしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"武蔵小山も、大井町をやるから武蔵小山ということではなくて、やはり武蔵小山商店街の力というのは飛び抜けておりますので、いわゆる路線端商店街と違う、広域カラーの東急電鉄を使って、お客を呼び込める力があったですので、このたびは地下鉄に直結したということで。","id":"exchange-037"},{"speaker":"三上委員","kind":"質問","question":"Ｃ地区のことなんだけれども、これすべてこのＣ地区の範囲で物事を進めていこうとして、一度失敗しているわけです。賛成する人たちだけで意見がまとまれば、これは区画として負担が３分の１になるのか２分の１になるのかわからないけれども、そういう範囲の中でそういう動きが出てきたならば、それはやりましょうという考え方をするのかどうかということについては、いかがですか。","respondent":"岩田まちづくり事業部長","answer":"そのときにも地元の方と区のほうで、当時６０年代に話のあったこの街区全体を１つの再開発地区として考えた案から、幾つかに分割をした案も検討はしたんですが、そのときでもやっぱりまとまらなかった。","id":"exchange-038"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう意味で、やっぱり区がもう少し入り込んでいって、いろいろな意見があると思いますけれども、そういった意見を集約した上で、援助というものを考えていっていただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3898#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":36838,"voices":98}},{"id":"h19-20071127-9","meetingId":"h19-cm11","date":"2007年11月27日","dateIso":"2007-11-27","committee":"文教委員会","time":"午前１０時０２分～午前１０時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"の「８３運動年末キャンペーン」の実施","agenda":"の「８３運動年末キャンペーン」の実施","exchanges":[{"speaker":"山内委員","kind":"確認","question":"内容３の（３）で、放送期間のところで、１点だけ確認を。これ、何で水曜日はやらないんですか。","respondent":"富田生涯学習課長","answer":"昨年の１月には、１月１０日、３学期の初めから流したんですが、水曜日、子どもたちは早く下校しまして、３時の放送を聞いて外に出たら、もう子どもは通らなかったという苦情が参りまして、その苦情をいただいてから水曜日は除き、月曜日、火曜日、木曜日。","id":"exchange-001"},{"speaker":"西本委員","kind":"提案","question":"確認をさせてください。キャラクターなんですが、キャラクターの著作権とか何か、そういうのは発生しているんでしょうか。提案者がおられると思うんですが、それは自由に皆さん使っていいのか、どういう関係になっているのかということと、それから、防災無線のほうですけれども、今回キャンペーンという形で、キャンペーンという形のほうが周知しやすいかなという感じがするんです。","respondent":"富田生涯学習課長","answer":"次年度も引き続きこういったものの作成は取り組んでまいりたいと考えています。防災無線による呼びかけをキャンペーンでやるのかどうかという点ですけれども、防災無線で流しますと、大変区民の方からの問い合わせが鳴った途端に殺到致します。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"今回キャンペーンという形なんですが、ずっとやったほうがいいのか、定期的にキャンペーンみたいな形でやったほうが啓発になるのかという、そこはちょっと様子を見ていただいて、効果があるほうの手法を今後、行ってほしいなと思っています。それと、個人の登録商標になっているんですね。これは、そうすると、使用料とかいう形は発生していないというふうに考えてよろしいですか。","respondent":"富田生涯学習課長","answer":"この件については、経費等々、支払いは全く不要であります。","id":"exchange-003"},{"speaker":"金野委員","kind":"質問・要望","question":"改めてこの８３運動はありがたいし、これからもぜひ続けていただきたいというところで、これまでのこの８３運動をしての効果というんでしょうか、どのような効果、いい点、悪い点というか、これを実施をしていく中で、どれぐらいの状況が、区のほうで把握をされているのか、そういう状況をお聞きしたいのと、あと、周知の面で、自治会、町会の方、あと公共の掲示をというところで、もっと広く。","respondent":"富田生涯学習課長","answer":"今回はポスターについてはそういった公共施設ですとか、公有車等々でということで作成をいたしましたが、今後、年度内にできるかどうかわかりませんが、そういった協力、張りたい、張ってあげたいとおっしゃる方についても、何らか、広げていけるような。","id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"それで、ＰＴＡの方たちとも協力をということなので、お母さんたちがジャケットを着て見回ってくださる姿をよく見かけますけれども、あの体制というのはどのようにというか、学校で何人かのお母さんたちが交代でいつもやっていると思うんですが、この８３運動とちょっと離れてしまうのかもしれませんが、そこら辺の連携というのは、あれも８３運動の一つのものでよろしかったでしょうか。","respondent":"富田生涯学習課長","answer":"各学校の単体での取り組みではないかというふうに思います。特に日が暮れるのが早くなって、下校の心配などをそれぞれの学校のＰＴＡがされて、学校ごとの取り組みを自主的にされているものと聞いております。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"いろいろなところで、いろいろな形で見守っていくというのが大事かなと思いますし、また、この大都会の中ですから、地域で知らない顔というのは見つけにくい、そういったところもあると思うので、皆さんでアンテナを張っていくという思いや態勢は強化していくべきだなとも思いますので、これからももっともっと内容を充実し、また検証しながら進めていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（慎）委員","kind":"質問","question":"そういう点で、やはり子どもが、この８３運動というのは地域の人たちがやっているんだよということを知ってもらうというのは非常に大事だと思うんですが、子どもに対する周知の方法というのは、何かとられているんでしょうか。","respondent":"富田生涯学習課長","answer":"子どもへの周知ですが、８３運動は継続してやってきておりますので、これまでも子どもたちが８３運動の絵をかいて、それを町会掲示板に張ってもらうなどなど、学校によりさまざま取り組まれております。","id":"exchange-007"}]},{"id":"topic-02","title":"の第６８回国民体育大会ハンドボール競技の実施","agenda":"の第６８回国民体育大会ハンドボール競技の実施","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ちょっとその辺がひとつわからないのと、あと、開催経費でかなりな金額、予算が組まれて、それぞれいるわけですけれども、東京都もこれに匹敵するか、あるいは若干ずれるのかわからないですけれども、開催のための地元負担というのはどういうふうになっていくのか、今までの経験のところでいいですから、教えていただきたいと思います。","respondent":"富田生涯学習課長","answer":"ハンドボールにつきましては、幹事区が墨田区ということになっておりますので、全体の経費は、まだこれから算定していきませんと、１区だけで行う競技ではありませんので、まだまだ申し上げられないところでありますけれども、会場等の整備等々も、総合体育館。","id":"exchange-008"}]},{"id":"topic-03","title":"品川南ふ頭公園野球場の利用および八潮北公園庭球場の早朝利用の開始","agenda":"品川南ふ頭公園野球場の利用および八潮北公園庭球場の早朝利用の開始","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"南ふ頭公園の、そちらは８枠とおっしゃっていたんですけれども、何時から何時というのを教えていただきたいのと、それから、３月で青空野球場が使用できなくなって、全部のところが返還という理解でよろしいんでしょうか。それから、八潮北公園のところです。１１月３０日までというのは、冬は利用が少ないということでよいでしょうか。","respondent":"富田生涯学習課長","answer":"品川南ふ頭公園の時間帯でありますが、午前７時から２時間単位で貸し出しをしてまいります。７時、９時、１１時、１３時、１５時、１７時、１９時、２１時ということで、８枠になります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"わかりました。そうですね、７時ですとちょっと暗いかなという感じもします。わかりました。すみません、あと１点ですが、早朝、７時から夜の１１時ということでは、早朝と夜間の管理というのはどういう形になっているのかをお聞きしたいと思います。","respondent":"富田生涯学習課長","answer":"こちら、管理はまちづくり事業部のほうで行うことになってまいりますが、現在と同じ体制で予定をしております。","id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問","question":"八潮北公園のほうなんですが、申し込み受け付けが平成２０年１月２１日で、括弧のところは平成１９年４月利用分というのは、これは訂正、間違いですか。","respondent":"富田生涯学習課長","answer":"申しわけございません。訂正をお願いいたします。「２０年４月」の間違いであります。","id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問","question":"それに関連してなんですが、申し込みのスタートというのは２カ月前じゃないか、３カ月前になるんですか。これ、４月利用分で１月２１日スタートということは、２カ月近く前からですが、通常の申し込みというのは２カ月前から可能なんですか。","respondent":"富田生涯学習課長","answer":"公営の施設、野球場、サッカー場、また庭球場等につきましては、３カ月前の２１日から月末まで抽選の申し込み受け付けをしまして、月が明けまして抽選を機械抽選で行うという形をとっております。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"２時間枠にしたのは、別にどうこうというあれはないんですけれども、２時間枠の利用実態というのはどの程度、どういうふうになっているんでしょうか。例えば品川南ふ頭公園の場合、１１時までの利用で、平日のお仕事をしておられる方たちの利用もこれで随分できるのかなと思っているんですけれども、ちょっとその辺の、利用実態というかしら、状況がどの程度か知りたいなと思って。","respondent":"富田生涯学習課長","answer":"ここはミニサッカー場としても利用できることから、都内のフットサル場等々の利用を見ますと、かなり深夜帯まで利用がされているということを踏まえ、まずは７時－１１時ということでスタートをさせたいというふうに考えております。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そうすると、大体品川区はどこでも住宅が結構ある地域ですから、９時ぐらいの利用で終了せざるを得ないというのがあるけれども、この南ふ頭公園については初めて１１時の時間帯を設けたという、そういうことでいいわけですね。それについては、これから推移を見守っていきたいと考えていますけれども。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-04","title":"の２その他","agenda":"の２その他","exchanges":[{"speaker":"山内委員","kind":"質問","question":"ちょっとお尋ねしたいんですが、前回の委員会のときに、１１月５日のその他のところで、ＡＬＴの講師派遣の件がありましたね、ＮＯＶＡの問題があって、１０月３１日で契約が解除になったということだったんですが、その後の状況というのをちょっと教えていただければと思うんですが。","respondent":"河野指導課長","answer":"ただ、小学校につきましては、前回の文教委員会でもご報告いたしましたけれども、品川区独自のカリキュラムで指導をしているという経緯がありますので、そのためにインタラックのほうに所属しているいわゆる外国人講師ですね、ある程度研修期間が必要であるということですので。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"そうすると、会社はわかりましたけれども、講師の数というんですか、それは今までどおり、ＮＯＶＡと契約していたときと変わらないという形でよろしいんですかね。","respondent":"河野指導課長","answer":"契約そのものの中身は従前と全く同様ですので、講師の数もＮＯＶＡのときと全く同数です。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4620#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":12642,"voices":61}},{"id":"h19-20071127-5","meetingId":"h19-cm11","date":"2007年11月27日","dateIso":"2007-11-27","committee":"総務委員会","time":"午前１０時０２分～午後０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"いろいろな話が出ましたが、まず確認しなければいけないことが、東京都の姿勢をどう感じていらっしゃるか。４４４項目については、ほとんど協議していきましょうというところ。それから、区割りのことを随分検討していこうということ。さらに、つまり２３区の区長会としては、このことについてどういうスタンスを持って臨んでいこうとしていらっしゃるのかということをまずお聞かせ願います。","respondent":"濱野区長","answer":"そこをねらってきて、都側は、いや、事務配分の話だって、区割りの話をしなければできないのではないのかというのが、１０月１０日の検討委員会での都側の主張です。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、そういう中でやっぱり私たちが一番心配するのが、２３区の区長がどういう考え方を持って、つまり、今の２３区のあり方、今の現状ではそうかもしれないけれども、この議論の結果、出口の部分でＡ市とＢ市がくっついていく、それからＣ市、Ｄ市がどうなっていくなんていうことを本当に考えているのかということはどうしても確認しなければいけないと思うんです。","respondent":"濱野区長","answer":"千代田、中央、港の財政力についても、ちょっとほかの区との違いが激し過ぎるという、そういう認識はあるわけでして、その辺でどういうふうに２３区の議論が進んでいくのかというのは１つ不透明なところがあります。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"区域の見直しをしなければならんのだということで押してくるということなんですけれども、区側の対応としては、まさしくそれは結果としてどうするかというのは我々が決めることなんだと、これは正しいことだと思うんですけれども、都側は逆にそれを押していくことによって、まともに４４４項目の検討ができないスタイルをつくっていこうとしているんじゃないかとさえ思えるわけですけれども。","respondent":"濱野区長","answer":"事務配分についての東京都側の対応をどういうふうに分析するかということでありますけれども、私は、少なくとも幹事会レベルでは、この４４４項目について区側に移すのを拒むということはないというふうに思っております。","id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"そこが今、区域のあり方というのを非常に全面に打ち出してきて、それの議論をしていかなければとか、それを議論をしていることの中からかなり強引に事務配分についての議論をリードしているというふうにも思えるんですけれども、そういう今後の対応、この区域の問題をどんどんしていくことによってというのは、成功すると向こうは本当に思っているのかという分析なんですけれども。","respondent":"濱野区長","answer":"相手の考えですから非常に難しいと思いますが、そう思っているふしは感じます。要するに、事務配分と抱き合わせで区域の話も盛り込ませようという意識はあるのではないかというふうに思います。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つは、区長から報告があった中身とちょっとずれてしまうかもしれないんですけれども、最初にこの都区のあり方の検討委員会で、まず事務配分をやって、それからその後、財政というお話がありましたけれども、ちょっと基本的なところで私がよくわからないんですけれども、財政に移っていったときに、財政問題に移っていったときに。","respondent":"濱野区長","answer":"そこは何通りか、今から予想することは難しいですけれども、何通りかパターンがあるだろう。それは１つは財調のパーセンテージの変更という一番小さな変化、これは区側が望むところではありませんが、東京都はそういう形で出してくるだろうなと思います。","id":"exchange-005"},{"speaker":"武内副委員長","kind":"質問","question":"今の菊地委員のことに少し関連するんですけれども、当初、税財源の話は後の話ということで、今、そうしないと進まないよということで４４４項目やっていらっしゃいますけれども、その出てきた中で、例えば具体的にはわかりませんけれども、この事業については、かなり赤だと、非常に厳しい財政財源のもとでやっているよという中で、例えば、そういったことを区側が意識をされた上で交渉に当たるのか。","respondent":"濱野区長","answer":"建前論で戦うべきか、あるいは現実論で戦うべきか、これはその１つの仕事を見て、財政負担ばかり大きいのに区民にとってあまりメリットがないというようなことであれば、そうっと、ということも必要でしょうし、それは個々具体の判断。","id":"exchange-006"}]},{"id":"topic-02","title":"議案審査に移ります。 第８０号議案、平成１９年度品川区一般会計補正予算","agenda":"議案審査に移ります。 第８０号議案、平成１９年度品川区一般会計補正予算","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"ただ、これから本予算があって、何年間かにわたって予算をつけていくことになるわけですけれども、区で考えておられる平成２７年度までに９０％の耐震改修を行っていくんだという流れで考えたときに、果たして、確かに出だしですのでいろいろな考え方があるのだと思いますけれども、この程度の予算でいいのかなというのがあるんですけれども、ちょっと基本的な考え方をお聞かせ願います。","respondent":"日下部企画財政課長","answer":"ですから、当然のことながら、来年度、平成２０年度の当初予算以降、今ご質問にもございました平成２７年度までに９０％というのは、これは大変大きな目標でありますので、今後平成２０年度以降の予算の中で本格的なそういう１つの計画実現に必要な予算を計上していく。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"確かに実効性という問題であるんだと思いますけれども、予算１つ１つを見ますと、当面一番必要なのは、実効性の問題確保については手厚く、当面は極めて大事なものだろうなというふうに思うんですけれども、予算全体に対して手厚い、もっともっと幅を広げてもいいのではないかなと思うんですけれども、ちょっとそこだけ考え方として教えていただければ。","respondent":"日下部企画財政課長","answer":"ですから、今回はこういう計上をさせていただいたわけでありますけれども、今回も３月までの間に個別訪問ということで、今までなかったやり方をしよう、つまり、パンフレットをつくってそれをただ配るだけではなくて、１軒１軒お宅を訪問しまして。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"本当にそうだと思います。最後に１つだけ。今お話しされた個別訪問の委託で４３０万円、もしわかれば、具体的なこの辺の、個別訪問の具体的な委託の流れを教えてください。","respondent":"日下部企画財政課長","answer":"ちょっと具体的にどうするかというのはこれからその辺の手順も含めて所管のほうで詰めていく中身ですので、いずれにしましても、整備地域の一番危険度の高いところを中心にして個別訪問、さらにまた個別訪問をするということになれば。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問・要望","question":"そうすると、補正予算は当初予算のときには入れきらなかったよ、だけど、出費を見ていたら、出入りとの関係でこれならできそうだということも含めてやりますよというものと、それから、その間に状況が変化が、法令が変わったとか、今回の場合も、一応、変化なのかどうかわからないけれども、中間の取りまとめをやったら拡充しようという話題になったよ、だから拡充しようと。","respondent":"日下部企画財政課長","answer":"しかも、それについては、緊急性があるものについては、やはり来年度を待つよりも、少しでも早く、いち早く着手する必要があるだろう、そういう認識のもとで今回の補正措置をとらせていただいたというものでありますが、先ほど申し上げましたように。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"全くそれはよくわかっていて聞いているんです。それと、補正をやって何か仕事をするために予算をつける、支出のほうを決めるわけですね。もうちょっとやれば、あれだけ貯金を持っているんだから、少しでも、もうちょっと最初から広げておいてやってくれたらよかったのにという思いになる部分もあるんですけれども、その辺についてはどういう考え方でしょうか。","respondent":"日下部企画財政課長","answer":"じゃあ、残りをどうするのかということで、今、委員ご指摘のように、基金から一部これを取り崩しをするという手もありますけれども、幸いなことに今回、財調につきましては、当初予算で見込んでおりました以上に８月に当初算定が出て。","id":"exchange-011"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"土井委員","kind":"質問","question":"区長会のほうで、今、この地方税収格差問題に対応する要請ということで要請行動を行われたということでのご報告なんですけれども、これは具体的にはどのような要請行動だったのでしょうか。区長会の皆さんも何人か、会長をはじめとしてその「様」と書いてあるところにお出かけになって主張された、こういう考え方、そういう見方でよろしいのでしょうか。そうすると、なぜここなのでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1768#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40048,"voices":56}},{"id":"h19-20071128-14","meetingId":"h19-cm11","date":"2007年11月28日","dateIso":"2007-11-28","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後１時４４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"林委員","kind":"意見","question":"凡人には非常に頭がこんがらがって何が何やらという感じもしますけど、一生懸命頭の中を整理しながら聞いていきます。全国で、説明の中には霞が関の情報もここを通じてという話も入っていた。なぜかというと、全国でたまに情報が漏れたというニュースを聞きますよね。こういうことをやっていても漏れるということがあるのかな。その辺の説明をもう１回聞かせてください。","respondent":"小野情報システム課長","answer":"私のほうの説明がちょっとあいまいだったんですが、共同運営サービスという電子申請、電子入札のサービスは東京都内だけです。東京都内の都も含めて５６の自治体が加盟をした協議会をつくりまして、この電子申請、電子入札の仕組みを共同で開発をしました。","id":"exchange-001"},{"speaker":"林委員","kind":"質問","question":"あのカードすら入っているのを読み取る機械を考え出すような人がいて、そうすると、このシステムそのものあるいは厳重な限られた回線の中でしか通用しないと言っていても、さっき説明されたフロッピーディスクから、証明書であり、秘密鍵、公開鍵を読み取られるという心配はないんですか。ないんですか。","respondent":"小野情報システム課長","answer":"もちろん認証局のほうもこういうデータをきちっと管理する。厳格に管理をするということによって、このシステムが成り立っているということで、委員がおっしゃるように、そういう点では人的な要素という部分がきちっとできないと非常に危うい要素もあるということです。","id":"exchange-002"},{"speaker":"林委員","kind":"質問","question":"それで、右側のページの３番の共同運営サービスにおけるセキュリティポリシーというところに、サービス提供事業者というのはわかります、委託先ですね。都区市町村というのは我々につながる。間に協議会というのが入っているんだけど、突然ここだけ協議会という名前があるんだけれども、この協議会たるものは何なんですか。","respondent":"小野情報システム課長","answer":"これはちょっと省略しておりますけれども、東京電子自治体共同運営協議会ということで、この共同運営の主体になっている部分です。これは先ほど申し上げましたように、都区市町村５６団体が加盟をして、このシステムそのものを運営している協議会です。","id":"exchange-003"},{"speaker":"林委員","kind":"意見","question":"そうすると、要は協議会というところには事務局みたいなものがあって、そこで仕事をする人間を指しているわけ、この協議会という言い方は。というのは、一番最初に委託先があって、後ろに自治体があって、その人たちなんでしょう、この協議会というのは。そうすると、協議会で働いている人間と思えばいいわけ、これは。","respondent":"小野情報システム課長","answer":"これは現実には東京都の中にございまして、事務局が設置をされておりまして、そこでいろいろな利用自治体の調整とかを行っているわけですけれども、実際この協議会は総会と運営委員会とか先ほど申し上げましたセキュリティ委員会とか、こういう幾つかの組織でなっておりまして。","id":"exchange-004"},{"speaker":"林委員","kind":"意見","question":"だって、５６の自治体が集まってこういうことをやろうよと言って、専門の局があってやっていて、その上に事務局なんかあるとよけい危険が増すんじゃないのかなという気がする。なぜこういう場所をつくらなきゃいけないのかというのが、だって安全を高めるためのシステムでしょう。なるべく外部というか関係者以外は入らないという考え方にならないといけないと思うんだけど、その辺は考え方としてどうなの。","respondent":"小野情報システム課長","answer":"そうすると、５６のすべての事業者から直接監督をするということになりますと、やはり現実的には１本でやっていきませんと、実際の運営というのができませんので、そういう点ではきちっとした運営のルール、仕様、費用の負担の問題。","id":"exchange-005"},{"speaker":"林委員","kind":"意見","question":"品川区の中の話で、右側のページの４番目に書かれている青で色づけしている文章なんだけど、これは情報システム課の考え方をあらわしているのか、品川区そのもののセキュリティに対する考え方をあらわしているのか。なぜかと言ったら、この一番最後の言葉、理解した上でログインしてもらっているという言い方が、このセキュリティが一番危ないなと思う言葉遣いなんです。","respondent":"小野情報システム課長","answer":"大変申しわけありませんでした。ご指摘のとおりです。私のほうでも資料の確認、この部分漏らしていたこともございまして、当然情報セキュリティ、守らなければいけない。これは徹底をしませんと、どうしてもきちっと守れません。","id":"exchange-006"},{"speaker":"林委員","kind":"質問・要望","question":"最後に、この裏面の矢印で１番から７番まで行っているんだけど、この下の段の赤い大きい送信、受信というところのセキュリティを図って守られて送られていくんだけれども、これは逆流というのはないんですか。逆流してくるとまた危ない感じを持つんだけど、それを聞かせてほしいのと、最後に品川区役所でこのフロッピーディスクを使える職員、それからフロッピーディスクが出ている業者の数を教えてください。","respondent":"小野情報システム課長、中島経理課長","answer":"逆流はございません。使える職員ということにつきましては、契約係の職員に限定をしております。ちょっと手元に今細かい資料はないんですけれども、品川区の登録業者は約４,０００業者ありますので、品川区に関しましてはそのくらいの企業者がＩＤを保有しているというふうに考えております。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"このシステムはいつごろから運用されているのかということなんですけれども、都の共同運営センターというのは前回お話のあったように平成１７年からということでよろしいんでしょうか。こちらの総合行政ネットワークのほうはいつごろから使っているシステムなんでしょうか。","respondent":"小野情報システム課長","answer":"センターのほうの運用ですけれども平成１７年からサービスを開始しているということで、その前にいろいろな登録の事務とかそういう形での業者登録だとかあるいは利用者の登録とかありますので、実際には平成１６年の後半から稼働しているという形になっております。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"いやいやこれはまだ数十年先まで大丈夫であるとか、そういった見通しといいますか、時間的な流れを教えていただけますか。","respondent":"小野情報システム課長","answer":"この東京電子自治体共同運営サービスのシステムにつきましては、毎年セキュリティ監査というのを外部機関に委託をして共同運営協議会のほうで実施をしております。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"ご説明の中で、侵入を受けたことはない。漏洩は人の部分からの漏洩であるというようなお話だったんですけれども、まさに情報が漏れたり改ざんされたりというのは、やはり人のところが一番弱いと思うんですよね。ちょっとその辺、まとめて教えていただきたい。","respondent":"小野情報システム課長","answer":"ここのところはどうしても決定的に技術的に何かで防止をするということはできない部分なんです。やはり職員のモラルという部分に負うところが大きいということで、やはり私どもとしてはそういう点で、このセキュリティの基準に基づいて各課で実施手順というのをつくっております。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"品川区の職員の方に悪意を持ってアクセスということはないと信じているんですけれども、例えば他の自治体ですとか、さまざまなところが使える。そうすると他の部署といいますか、品川区以外のところで何かそういった悪意を持って使った場合に、品川区というところに影響が及ぶことはない仕組みになっているんですか。","respondent":"小野情報システム課長","answer":"国の定めているプライバシーマークといった基準に基づいて、自社の規定をきちっと定めて職員の教育をするというふうなことも、共同運営のセキュリティポリシーの中に定められておりまして、それに基づいてそれぞれの事業者もきちっとした実施手順を定めて徹底をする。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"最後１点なんですが、先ほども出ました電子自治体共同運営協議会なんですけれども、この組織のイメージを持ちたいんですけれども、これは５６自治体から例えばすべて人が派遣されて大所帯でやっているとか、いや、もうちょっとスリムな組織であるとか、あるいは出向の人ばかりとか、専門家がいるのであるとか。イメージをつくりたいんですが、どんな組織になっているんでしょうか。","respondent":"小野情報システム課長","answer":"そのほかに附属の機関として、先ほどの情報セキュリティ委員会、これは情報セキュリティ、複数の自治体で利用しておりますので、あるいは事業者が絡んでおりますので、すべての構成団体がきちっとしたセキュリティを守っていく。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"協議会というと、そういう組織になるのかなと思うんですけれども、実際にこの協議会が民間の事業者に対して監督などを行う実働部隊というのはどこになるんですか。","respondent":"小野情報システム課長","answer":"実働部隊は協議会のセキュリティ委員会の中で、ここにもこのセキュリティ委員会を担当している事務局がありますので、実際はここのところのいろいろな判断、指示に基づいて事務局が業者を監督するという形になります。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"ここの情報セキュリティ委員会の方々というのが、まさにこういったシステムの専門的な知識も持って、機動力も持って、多分常駐でいらっしゃるということなんでしょうか。","respondent":"小野情報システム課長","answer":"情報セキュリティ委員会自体は、各自治体からの運営委員の構成メンバーがこの構成メンバーになっているというようなこともございまして、セキュリティ委員会が常に設置はされておりますけれども、会合自体は毎日やっているというようなことではございません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"初歩的な図の見方なんですが、表面のところの左の図に共同運営センターとまず真ん中に書いてありますね。その下の※印のところに網掛部が共同運営センターの物理的な範囲、と書いてあるんですが、この共同運営センターは東京電子自治体共同運営センターと思っていいんですか。ちょっとそこのかかわりが、この共同運営センターというのが何になるのかというのをまず最初にお伺いしたいんです。","respondent":"小野情報システム課長","answer":"この物理的な範囲というのは、回線の部分、この共同運営センターが設置管理をしている回線ということで、それぞれインターネットにつながっているまでの部分、それから総合行政ネットワークのオペレーションセンターまでの部分。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"共同運営センターとこの東京電子自治体共同運営サービスのここの関係というのは、この図からどういうふうに見たらいいのか。","respondent":"小野情報システム課長","answer":"ですから、その協議会のやるサービスをそのまま受託をして運営しているというのがサービス事業者で、そのサービス事業が実際に機器を置いて業務を処理している場所が共同運営センターという形です。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"その辺のシステムを教えてほしいのと、ここの部分での問題点というのがないのかどうか教えてください。","respondent":"小野情報システム課長","answer":"ですから、上の商業登記と民間認証機関はいわゆる商業的なこういう入札などに関して企業が使う認証局で、公的個人認証は個人が使う認証局という形になります。この３つの種類が現在電子的な手続きをやるために国が定めている認証局です。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"個人的なところはわかりました。商業登記の認証局と民間認証局というのはたくさんあるんですか。数的なものと、この手続きは費用がどのくらいかかるのか教えていただきたい。","respondent":"小野情報システム課長","answer":"費用なんですけれども、これはＫｅｙＳｉｇｎサービスということですので日本電子認証株式会社という機関になりますが、ここでは１年間の有効期間の場合は９,４５０円、２年間の場合は１万６,８００円。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"法的に厳格に基準があるということなんですが、一番最初、問題点とか特に事故とか、この局のところでの問題点はないのかどうか、そこを教えてください。","respondent":"小野情報システム課長","answer":"先ほども申し上げましたように、このシステムの仕組み自体での問題点、セキュリティが危うくなっているというような部分での問題点というのは、今まで起きていないというふうに認識をしております。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"電子入札がこの間、進んできていると思うんですが、この間の国とか都での電子入札の計画というか、今後どういうふうに目標が立てられているのか。わかる範囲があったら教えていただきたい。","respondent":"小野情報システム課長","answer":"電子入札に限らず、行政の手続きについては国のほうはすべての手続きを電子化するというのは基本的な方針として出しておりまして、実際に国のいろいろな手続きについては、ほぼ９０％以上が電子でできるというふうな仕組みが整えられているというふうに聞いております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、２３区においても電子入札の導入に対してはまだまだ違いが大きいと、この間の視察に行っても伺ってきたわけですけれども、具体的に品川区においても始まってはいますけれども、今、国のところで９０％は電子入札にできるというご答弁をいただいたんですが、今後進むにしても、なかなかこういうのに参入できない部分に関して、手だてというか、その辺についてのお考えがありましたら。","respondent":"中島経理課長","answer":"電子調達ということで今どんどん拡大していますけれども、これはパソコン等を通じて業者登録をしていただくというのが大前提になりますけれども、そういった意味では今の委員のおっしゃるそういった機能を持っていないというか、小さな会社。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問・要望","question":"それとも認証番号というか暗証番号を知っていればアクセスできるのかどうか。その場合には最低限どこを理解してもらわなきゃいけないのか。フロッピーディスクのことなのか、それとも全体のここをすべて、今、我々が説明を受けたようなことまで理解した上で、４,０００業者の方が加入されているというんですけれども、その辺はどうなっているのかというのを教えていただけますでしょうか。","respondent":"小野情報システム課長","answer":"したがって、そのものが格納されているフロッピーディスクの管理については非常に重要で、厳格にしなきゃいけないものなのだというところまでは、ご理解をいただいてお使いいただけるかなというふうに思っております。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"そのときに、本当に操作がやっとな方が今のこんなことまでわからないと思うんですけれども、そういう面ではそのフロッピーディスクをもらったときに、それをしっかり管理してくださいということで、使い勝手はそんなに難しくなくて簡単な操作で、この中は非常にセキュリティが難しいのが入っているけれども、簡単な操作でできるんだということでよろしいんでしょうか。","respondent":"小野情報システム課長","answer":"それで、事前に証明書をとらなきゃいけないというふうなことも書いてありますので、その辺については十分、中身まで詳しいことを知らない方でも利用ができるというふうに考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"そこのセキュリティポリシーについてお伺いしたいんですけれども、1)のところにサービス提供事業者・協議会・都区市町村が遵守すべきルールとありますけれども、このサービス提供事業者の中に先ほど話にもありました認定局が３つありますけど、それが含まれているのかいないのか教えてください。","respondent":"小野情報システム課長","answer":"もう一つ、各自治体がそれぞれセキュリティポリシーを定めるということの内容にばらつきがあると、セキュリティが十分保たれないのではないかというご心配かと思いますけれども、この点については東京電子自治体の実施手順というものを定めましょうということで。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"各都区市町村のセキュリティポリシーが同一のものというお話でしたけれども、それと認証局とのセキュリティポリシーというのは、共通なものというのか、同レベルのものなのか、教えてください。","respondent":"小野情報システム課長","answer":"これは各自治体についても同じことが言えまして、私どものほうは電子自治体の共同運営に関するセキュリティの実施手順というのを独自に共同運営協議会のセキュリティポリシーに基づいてつくっておりますけれども、それだけではなくて、ここで言う3)。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"実施手順において具体的に定める事項、１から８までありますけれども、ここには含まれているのか含まれていないのかわからない、災害に見舞われたときにそれぞれの運用がどういう対応をとるのか。具体的には首都直下型の地震が起きたときに回線が途切れちゃう、電気も途切れちゃう。そういうところはどういうふうに今定められていらっしゃるんでしょうか。","respondent":"小野情報システム課長","answer":"今ちょっと具体的な文面をもってご説明できるだけの資料がないんですけれども、災害だとか事故に対する対応というものについてもセキュリティポリシーのガイドラインの中に項目がありますので、同じように定められているというふうに考えております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"今、手元に資料がないみたいですけれども、例えばこの電子自治体、便利な半面、電気が遮断されちゃうと何も動かなくなってしまって、復旧にもそれぞれ確認作業に時間がかかるのかなと思うんですよね。","respondent":"小野情報システム課長","answer":"ただ、時間については、この間の江戸川区での事故の後、国がライフラインについての電源という部分だとか、そういう部分で緊急のいろいろな通達を出して、特に供給事業者等に対して送電の回線を二重化するとか。","id":"exchange-027"},{"speaker":"石田（慎）委員","kind":"確認","question":"フロッピーディスクの件なんですが、このフロッピーディスクというのは僕がイメージするに昔あった３.５インチというんですかね、正方形の。あのフロッピーディスクでよろしいんでしょうか。確認申請をしてから送られてくるのかを確認させてください。","respondent":"小野情報システム課長","answer":"フロッピーディスクはおっしゃるとおり３.５インチの通常のフロッピーディスクです。","id":"exchange-028"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、今、フロッピーディスクがついていないコンピュータがほとんどだと思うんですが、今後このフロッピーディスクのままいくのか。それとも新しい記録媒体、今はＣＤ－Ｒ、ＤＶＤ－Ｒ等がありますが、そっちのほうに変更されるのか。今、検討は実際にされているのかどうか教えてください。","respondent":"小野情報システム課長","answer":"大変申しわけありません。ここのフロッピーディスクが今後どういうふうな媒体になっていくかということについては、国のほうで認証局の管理をしておりますけれども、どういうふうな方針でやっているかということについては、ちょっと私のほうでは把握をしてございません。","id":"exchange-029"},{"speaker":"石田（慎）委員","kind":"質問","question":"先ほどの話だと、ノートパソコン等からの情報が漏れるというんですが、ノートパソコンというのはあくまであちこちに持ち運べるという利便性のためにつくられたもので、こういった情報を扱う際にノートパソコンを使うというのはどうなのかなという思いがあるので、品川区としては今どういうような体制をとられているのか教えてください。","respondent":"小野情報システム課長","answer":"入退出管理につきましては、コンピュータのサーバー等の本体機器を格納している部屋、これは今、情報システム課のほうにありますけれども、そこに入るためにはまず職員証がありますけれども、それでマシン室という１つの部屋に入るときに職員証をかざして。","id":"exchange-030"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、情報というのが以前どこから漏れていたんですかね。それはノートパソコン等から漏れたと先ほどあったんですが、どうでしょうか。","respondent":"小野情報システム課長","answer":"先ほどお答えいたしましたパソコンが盗まれてというお話ですけれども、事例としてはこの共同運営のサービスとかそういうことではなくて、一般に例えば業務で使っているパソコンの中にいろいろな税務の関係であれば。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"すばらしいシステムだと思うんですけれども、もしもこのシステムが原因で何か事故があった場合に、どこが責任をとる仕組みになっているのかだけ教えてください。","respondent":"小野情報システム課長","answer":"共同運営のセンター、つまり委託をしている民間事業者の共同運営センターの範囲の中から漏れた部分については、受託のサービス提供事業者が責任を負うという形になっております。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"共同運営のセンターの中から漏れた、回線上からというのは多分ないのでありましょうけど、センターの中からという限定がつくと、では、それ以外の場合はどうなんだとつい聞きたくなるんですけど、どうでしょうか。","respondent":"小野情報システム課長","answer":"それに応じて責任を負うということです。","id":"exchange-033"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"最初に林委員から質問があった中でちょっとわからなかったのが、電子署名の一連の流れの中で5)のところで、送信、受信で逆流がないというようなお答えがあったと思います。それから、東京電子自治体共同運営サービス全体に対して、品川区として分担金なのか負担金なのか、それは幾らぐらいかかっているんでしょうか。","respondent":"小野情報システム課長","answer":"送信、受信の矢印のところについてのご質問ですけれども、私のほうで先ほど説明しましたのは、この経路を使って区の情報が外に流れるという心配はございませんというお答えをさせていただきました。","id":"exchange-034"}]},{"id":"topic-02","title":"財政（歳入）に関すること","agenda":"財政（歳入）に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"何か減らす方向での独自性というのが出せるのかどうかということと、今、何か品川区として独自課税を検討の俎上に乗せていらっしゃるかどうかということ、あるいは品川区としての独自課税についての考え方、財政需要ですとか、政策とのリンクですとか、そういった意味で、どういう場合なら独自課税をするかもしれないというような考え方というのがもし現段階であれば教えてください。","respondent":"日下部企画財政課長","answer":"現行のもの、減らすことも含めてどうなのかということでありますけれども、先ほどもちょっとご説明の中で申し上げましたけれども、地方税法という法律の中で税目、先ほど税の体系の中で一覧でお示しをさせていただきましたけれども。","id":"exchange-035"},{"speaker":"阿部委員","kind":"意見","question":"今、特に具体的に検討していないということで、これから先は意見になります。大変よろしいことかと思います。そのための税金を既にいただいているので、今は目的税でいろいろなことを出してくる自治体もあるかと思いますけれども、まずはやれる範囲の中で政策を立てていくという考え方で非常によろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問・要望","question":"豊島区のワンルームマンション税が平成１６年６月１日から施行とここに書いてありますけれども、約３年ぐらいたっていると思うんですけれども、例えばワンルームマンションがこれでちょっと減ったとか、そんなような状況がわかれば教えていただきたい。あれはこれとは関係ないんですか。それを教えていただきたいと思います。","respondent":"日下部企画財政課長","answer":"それがこの程度にとどまっているという見方もできますから、なかなかこの辺の評価というのは難しいかなというふうに考えております。それからもう一つ、杉並区のレジ袋税ですけれども、杉並区は一たんレジ袋税条例が可決成立をいたしました。これが平成１４年です。","id":"exchange-037"},{"speaker":"林委員","kind":"確認","question":"確認していきます。１ページ、下のほうにある税金の主な分け方というところ、これは何から引っ張り出してきたのかわからない。２番目の地方税、道府県税と市町村税というのかな、都が抜けているんだよね、それらに分かれるというふうに書いてあるんだけれども、都が抜けている理由と、それからいわゆる都道府県と市町村税に分かれるというふうにここにはっきり書かれている根拠があるんですか。","respondent":"武内税務課長","answer":"税法上の規定でこのように都が抜けていて道府県税というふうに入っていると認識してます。","id":"exchange-038"},{"speaker":"林委員","kind":"質問","question":"何で聞いているかは多分もうわかっていると思うんだけれども、法律的にこれが根拠があって都道府県と市町村に分かれているとすれば、今、東京都がせしめている２３区の分については違法ということになるんだけれども、そういうところに行きたいわけ。それについてわかっている範囲で結構ですから答えてください。","respondent":"武内税務課長","answer":"地方税法の枠の中で特例的に東京都と２３区の部分について明確に、地方税法何条かちょっとはっきりわかりませんけれども、そういうふうにうたわれておりまして、各都道府県においての固定資産税等は市町村で扱えるということになっているんですけれども。","id":"exchange-039"},{"speaker":"林委員","kind":"質問","question":"ここの話ではない部分が多いので別のところでやります。もう一つは普通税と目的税という分け方なんですけれども、意味はわかっています。一般財源に使うのと目的をもって使う使途を限定されているという分け方はわかります。その普通税として払う段階は普通税なんだけれども、区に一たん入った後、区として独自にこれはここにしか使わないよという目的税化というのは認められているんですか。","respondent":"日下部企画財政課長","answer":"これはあくまでも予算編成上の１つの考え方として可能ではないかと考えております。","id":"exchange-040"},{"speaker":"林委員","kind":"質問","question":"利用料という料金と税金の違いは何なのですか。僕が太宰府市民だったらそういうふうに問いかけるんだけれども。例えばほかの焼却の費用とか、今、事業系一般廃棄物は有料になっている。あれは税なんですか。それともいわゆるごみの処分料なのか。その辺、これを見ていると、もう既にあの事業系のごみは税金という判断をしてもいいような気がするんだけれども、その辺の考え方を教えてください。","respondent":"日下部企画財政課長","answer":"非常に難しいところはありますけれども、例えば今のごみ処理は手数料で歳入としているわけですけれども、これは一種の受益者負担の考え方というところだと思います、基本は。この場合、税とどういうふうに違うかというと、区として区民サービスを提供する。","id":"exchange-041"},{"speaker":"林委員","kind":"質問","question":"上乗せなんですか。例えば１２ページの一番最後、沖縄県の伊是名村は飛行機や船で入って幾らといったら１回幾らで利用料じゃないの。よそのことだからとやかく言っても品川区のじゃないからあれですけど、利用料と税というのは非常に難しい。そういう考えで、とにかく環境のことだとかいろいろ目的があって、取るものは取るぞという感覚なのか。","respondent":"日下部企画財政課長","answer":"なかなか難しいところがありますけれども、まず、前段のお話で申し上げれば、今、委員ご指摘のとおりですね。先ほどもちょっとご説明させていただきましたが、特定の例えば企業でありますとか、あるいはよく東京都の宿泊税も問題になりますが、住民にはかからないわけですね。","id":"exchange-042"},{"speaker":"林委員","kind":"質問","question":"僕は納得しないね。税金というと何となく違うんじゃないのという、よそのことですからさっきから言うようにあれですけど。全く違う形で以前やっていた住民税の一括納入の報奨金というのかな、還付というのかな、あれはやめて１０年ぐらいになるのかな。品川区、お金が余っている、余っていると言われているんで、復活というそのぐらいの区民サービスも考えてもいいんだけれども、いかがでしょうか。","respondent":"武内税務課長","answer":"これは何でやめたかと言いますと、サラリーマン特別徴収の方につきましてはそういう制度がないわけです。毎月給与天引という形になります。それで税の公平性という視点からこういうものがいかがなものかという形で廃止になったというふうに私は認識しております。","id":"exchange-043"},{"speaker":"林委員","kind":"質問","question":"特別徴収の人だって一番最初の総額来るんだから、総額幾らで毎月この額になりますよと、１２カ月に分けて。よそでやらないことを品川区は好きなんだから、一番にやったらいかがでしょうかね。もしかしたらそんなことやったら、例えば交付金を削られるとか、そういうことがあればまた別な話ですけど、そういうことがないとすれば、１つの施策として打ち出してもいいと思うんですけれども、いかがですか。","respondent":"武内税務課長","answer":"そういう方策もあるのかなと、非常にいいアイデアだというふうに私も思いますので、税務課長の立場で税のことをもうちょっと研究させていただきたいと思います。","id":"exchange-044"},{"speaker":"林委員","kind":"意見","question":"ただ、法で定められた部分があるので法にさからってはできないということなんだけれども、これは２３区で相談すればいいと思うんだけど、さっきから言う還付するべきものは還付していくんだ。だけど、上にとやかく言われない、なぜかと言ったら直間比率というのが税には必ずついてまわって、それが公平感とかそういうところに払う側にとっては非常に大きい問題であると思うんだよね。","respondent":"日下部企画財政課長","answer":"地方税も都道府県と市町村でこれから道州制とかいろいろそういうことで変わってくるとは思いますけれども、そういう意味ではそれぞれ個々人あるいはそれぞれの法人につきまして、それぞれの負担能力の問題というのもかかわってまいりますので。","id":"exchange-045"},{"speaker":"山内委員","kind":"質問・要望","question":"わかる範囲のところで教えていただきたいんですが、最後の前のページに宿泊税が出ておりますけれども、この平成１４年から実施されたということで、当時、石原都知事は非常に地方からバッシングを受けまして、何でこんなところで税金をかけるのかとか、そのようなことがありまして、それによって例えば宿泊利用客がこの税金によって減ったと、私はそうは考えられないと思うんですが。","respondent":"日下部企画財政課長","answer":"あくまでもワンルーム、小さいものは最小限にして、そのかわりファミリー向けの住宅、マンションのほうに少し誘導していこうというような１つのねらいでこういう形をとっておりますので。","id":"exchange-046"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"この辺、政策的な考え方でいくと、駅前にそういうビジネスホテルができるということがある程度抑制をかけないでいいのかなという考え方を持ったときに、今の宿泊税は東京都は１万円以上の宿泊に対して１００円かかっているけれども、逆に品川区としては今のビジネスホテルが１万円かかるわけがないので、もっと低い金額に対してあくまで抑制という意味で考えるということは検討の余地はないのか。","respondent":"日下部企画財政課長","answer":"さらにそれに対して例えば一定の抑制をかけるとしても、どういう方法が考えられのか。必ずしも税ばかりではありませんので、そういうことも含めていろいろ多角的な検討が必要になってくるのではないか。このように考えております。","id":"exchange-047"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"ちょっと税だけではなくて違う話になってしまうかもしれないけれども、例えば大井町の駅を考えたとき、これからも大きなものが２つできてくる。オフィスビルならまだその人たちは買い物だとか帰りに寄ってくれるとかという可能性があると思うんですよね。そういう点で、何かちょっと使えないかなという思いがありますので、どちらになるかわからないけれども、検討していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"東京都が法定外税をかけるのに幾つもメニューを出してきているわけですけれども、例えばホテル税に関していえば、導入のときに税額は１００円、２００円と低いですけれども、それぞれのホテルの中でのシステム変更というのは何千万円単位でいきなり支出を迫られて、業者としては非常に苦しい状況があったかと聞いておりますけれども。","respondent":"日下部企画財政課長","answer":"それは十分に可能です。自治体間で意見を申し入れるということはいろいろな形で行われている。そういうことも含めまして可能です。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/190566?Template=document&Id=5830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":47456,"voices":115}},{"id":"h19-20071129-16","meetingId":"h19-cm11","date":"2007年11月29日","dateIso":"2007-11-29","committee":"街づくり特別委員会","time":"午前１０時０２分～午前１１時３３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"日程に入ります。特定事件調査の地区計画に関することのうち、地区計画の現況","agenda":"日程に入ります。特定事件調査の地区計画に関することのうち、地区計画の現況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改めてたくさん地区計画がこのように決定しているなというふうに、とりわけ再開発等促進区型の地区計画では、区としてはいろいろさまざまな更地にするときの補助金を出したりとか、あるいは実際にアドバイスをされたりとか、いろいろ再開発に関しては、すごく熱心だという印象が強いんですけど、明電舎のシンクパークもオープンしましたけども、どんどんこれからも説明にもありましたが、特に五反田。","respondent":"青木都市開発課長","answer":"地区計画制度につきましては、経済的な事情というものは一切考慮してございません。ですので、需要見込みがどうであるかについて考慮して地区計画を定めるというものではなくて、まちづくりがどうあるべきかということを考えて、地区計画を設定しているものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それは全く関係ないとは言えないと思うんですけども、逆に言うと、見込みがなく、計算もなくどんどん建てるというのは、しかもそこにいろんな形で補助金とか税金を入れるというのは、全く区民から理解を得られないと思うんですが、その点については、私はそこを考慮した上で地区計画というのはもちろん定めるべきだと思いますし、あと促進をする立場に立つんであれば。","respondent":"青木都市開発課長","answer":"まちづくりというものは、都市政策あるいは都市経営という視点から当然政策的な判断は加わった上で決めているものですけれども、その手法として、制度として地区計画を活用するということでありまして、その都市経営がどうであるかということと。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"この地区計画が定められるということで、そういったものもいろいろ建つことも可能になるわけで、その地区計画を定める上で、何らかの区の判断といいますか、後押しがないとこういう地区計画は定められないと思いますし、定まることによって、オフィスビルやあるいはマンションとかというのが、しかも高いもの、ものすごい高層ビルがどんどん建つと思うんですけども、その辺でちょっと私は理解。","respondent":"岩田まちづくり事業部長","answer":"したがいまして、先ほど委員がおっしゃったように、いわゆる市場原理の中で高層ビルを建てて、マンションを建てるか、あるいはオフィスを建てるかということが市場に合うか合わないかというのは、そこで事業をなされる事業主が十分検討されて計画を立てられるわけですので。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと話が変わりますけども、ちょっと単純に気になっているんですが、マンションがどんどん建っていますけども、建て替え時期がやっぱり来ると思うんですけども、すごくこの１０年ぐらいでかつてないぐらいのものすごい量の高いマンションビルが建っていると思うんですが、いずれ建て替え時期が来ると思うんですけども、それはビルによって違うと思うんですけど。","respondent":"岩田まちづくり事業部長","answer":"前にもちょっと一度ご説明させていただいたことがあるんですが、品川区のまちづくりの契機となった大きな要因というのは、昭和４０年代後半から５０年代。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それを住民の方に説明するのも難しい状況にあると思うんですね。でも、住民の側とすれば、高いものが建つことで、実感的に確実にどうも歩きにくくなったとか、風環境が悪化したということを体感している方も多いわけなんですけども、これからのまちづくりにおいて、風環境に関して、ちょっと対策みたいなものを考えているのか、その辺はどうお考えなのか、ちょっとお伺いしたいと思います。","respondent":"青木都市開発課長","answer":"もし課題があるとしますと、建物が建つ段階、建って、工事中の段階とでき上がった段階というものは、それぞれ環境が違いますので、原則現在の評価の仕方は建物が立ち上がった後、環境がいいか悪いかというものを評価していますので、建築中のものについては。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"検討中ということなんですけど、もし考えているところでも、どういった対策があるのかというのをちょっとお伺いしたいのが一つと、あと、再開発で大崎地域ではアセスメントが除外されているという話ですけれども、でも、地区としてはちゃんと独自のチェックをしているという話だったんですけれども、本来何でこの地域からアセスが除外になったのかというのはいろいろ法律があるんでしょうけれども。","respondent":"青木都市開発課長","answer":"個別の開発問題につきましては、所管委員会のほうでご議論いただいております。詳しくは別にご説明したいと思います。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"地区計画一覧の中で、再開発等促進区、これをちょっと見ていただきたいんですが、備考のところで、再開発等促進区が１１ありますが、その左手の告示番号をご覧になっていただいて、そうすると、１５番の東五反田二丁目地区、これだけが、ほかは東京都告示ということでありますが、そこのところだけ品川区告示ということになっておりますけれども、これはどのような違いで、どういうふうに。","respondent":"阿部都市計画課長","answer":"ただ、この東五反田二丁目地区につきましては、地区計画の面積は３.１haとなっていますけれども、再開発等促進区を定めた区域が３ha未満ですので、東京都ではなく、品川区決定になって、品川区の告示ということになったです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"非常に地区計画をかけていくということは大切な、用途地域がこういう状態だと、これが主力になるんでしょうから、そういう形の中で、街なみ誘導型というのもまた一つ出てきて、ここが非常にポイントになるだろうと思うのでそこのところを聞きたいんですが、ここに至る例えば街なみ誘導型にしても、ここに至るまでには相当皆さん、南品川は早かったけれども、相当時間がかかるとなると。","respondent":"伊勢住環境整備担当課長","answer":"まちづくり専門家派遣を実施しているところは、現在小関地区で１地区あります。それから、コンサルタントを派遣していないですけれども、それぞれのまちで独自に専門家等のもとにまちづくりを進めたいというところが戸越公園の駅前あるいは武蔵小山周辺です。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"北品川地区はどうですかなんていう話は建設委員会でもちょっと話が出たんだけれども、そういう誘導をしていこうと、あるいは武蔵小山なんかも今商店街が中心となってそういうこともされているということなんだけど、行政側として話がもちろんあってから動くのが一つだけど、誘導しようかなと思うような地域、例えば密集市街地なんて話が来てくれればありがたいと思ってぱっと行くわけだけど。","respondent":"伊勢住環境整備担当課長、岩田まちづくり事業部長","answer":"そういう中で、特に専門家というのは懇談会自体に区がもちろん出席してコンサルタントもついてくるわけですけども、防災性の向上、あとはいろんな用途のことだとか、建物の高さのことだとか。今防災について、密集事業地区４地区、これは将来的にはできれば戸越のようなきちっとした地区計画を定めていきたいと考えています。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"密集地域も、例えば旗の台周辺、これですとローマ数字のＩのところですか、その下がっていった南側ですね、こちらのほうも品川区に劣らず密集している部分だと思うんですね。","respondent":"伊勢住環境整備担当課長","answer":"旗の台と区境と面していますけれども、基本的にここでは特に地区計画というようなことはないんですが、密集事業ということで考えますと、基本的に地域危険度が高い地区、ここは密集事業地区を指定しまして、そこでこういう事業をやっているんですけど。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"確かにほかの区のことはなかなか口出しはできないと思うんですけれども、例えば今お話の中で、当該大田区との境のところで、大田区に対して、例えば品川区はこういう事業をやるよとか、大田区は今こういう状況だよとか、そういうような交流といったらおかしいんですけれども、話し合いみたいなものはされているのかどうかということだけお伺いしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"年間４回、あるいは３回ぐらい開催しまして、そこで各区の意見交換をしたりしておりますので、そういうところでご意見を聞くとか、あるいは意見交換する、こういう機会を設けてあります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"基本的なことを教えていただきたいんですが、まず、先ほども質問ありましたけれども、告示番号が品川区と東京都がありますけれども、先ほど１５番のところで、再開発等促進区のエリアが３ha未満ということだということですが、ほかのところもそういう認識でよろしいんでしょうか。そういう考え方でよろしいんでしょうか。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたけれども、ほかの地区で再開発等促進区を定めている区域につきましては、その再開発等促進区が３ha以上です。一般型とか、そのほかのものにつきましては、そういう３haということはございませんので、すべて品川区で決定です。そういうことです。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"それで、決定権の違いだという話がありましたけれども、品川区が決定の場合と、東京都の決定の場合はどういう流れの違いがあるのかということと、それに関連して、例えば地区計画をこのエリアにしますよと東京都から地域を指定されてくるのか、それとも品川区の中でこういった計画をやりたいんだけどというふうな形で指定されるのか、そうでなければどういうふうな形なのか。","respondent":"阿部都市計画課長","answer":"こういう地区計画を定めたいんだけれども、同意をいただく。従前は、承認という形でございましたけれども、法改正になりまして、それが同意、東京都の同意を求めるという形になります。それで、区で決定をしていくという形になります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"そういう形にすると、それは品川区の中でどういう経緯があって、そういうふうに決められたのか、例えば、品川区の中でまちづくりをどうしていくのかというところでこれらを決定していくという流れなのか、それとも、住民サイドからここをこういう形にしてほしいというものがあって、こういう形になったのかということをお聞きしたいんですけど。","respondent":"阿部都市計画課長","answer":"先ほど部長が答弁申し上げましたけれども、まずは品川区の場合には市街地整備基本方針という品川区のまちづくりの基本方針があります。それに従いまして、大崎をはじめとして、さまざまな地域でもそれに基づきましてまちづくりを進めていくという、これが基本です。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、品川区のまちづくりの構想といいますか、こういうまちにするんだよというふうに決めて、それで、じゃあ、そこの地域が指定され、決定されましたというふうになったときに、じゃあ、それをどういうふうに進めていくかということですね。ほかのところに対しては、そういう形で順調に動いているという認識でよろしいんでしょうか。","respondent":"阿部都市計画課長","answer":"そのとおり進めていきたいと考えています。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"最後に、二つほど。関係ないとは思うんですけど、景観法との絡みの中で、こういう地区計画になってくると、どういう整合性が出てくるのかなと。現在はじゃあどういうのが主流で、計画がいろんな、防災街区整備地区だとか、いろいろありますよね、それを指定していくのかという、そこら辺の、いろいろ補助金等々を含めて変わってくると思うんですけど、それはどういうふうに整理して進めていくものでしょうか。","respondent":"阿部都市計画課長、青木都市開発課長、伊勢住環境整備担当課長","answer":"南品川三丁目につきましては、本来はもともとの地元の方々は、高さ規制だけでのスタートでしたけれども、私どもの考え方はそうではなくて。ですけれども、その中で、例えば密集事業で道路を広げるためにセットバックしてもらえるとか、不燃化のために建て替えてもらうとか。事業導入として地区計画だとか、あるいは場合によっては都市計画の変更、高さを何ｍ以上にしなさいとか、こういうことが前提で事業導入をやっている。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"地区計画のマップで、色のついていない部分というのがかなりあると思うんですが、実際これから徐々に埋めていくかと思うんですが、現在計画は計画で色がついているところもこれからだと思うんですが、白い部分、この中で白い部分は全く現状としては手がついていないというふうに考えてよろしいでしょうか。","respondent":"阿部都市計画課長","answer":"白い部分は全く手がついていないということではなくて、先ほど申し上げましたけれども、市街地整備基本方針の中では、この地域についてはこういうまちづくりをしていこうという考えはありますけれども、今のところ事業、個別の事業として入っているということではないです。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"もちろん税金その他いろいろ補助もあると思うんですが、その辺について、やはりちょっとお聞きしたいのは、このままやっぱり少しずつ地区を限定して、また１０年後、またほかの地区に移っていくかと思うんですが、そういうふうにやっていくお考えでしょうか。","respondent":"阿部都市計画課長","answer":"例えば、今委員おっしゃいましたけれども、防災性はどうあるべきなのか、そういう議論を経ながらその地区をどうしていくのか、その中で、例えばある一定の規制を加えつつ、斜線制限等をしながら建て替えを進めていって。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"どちらが先かということはあると思うんですね。ただ、こういうふうに限定されると、そこの地域は確かに促進しよう、皆さんの発意で動いて、その地区を限定して、区のほうで指定して変えていく。やりたいという人がそこでやれない。そのうちだんだん網がかかってきて、１０年後か２０年後にやる。そのときにチャンスがなくなっちゃうということもあるのかなというふうに思うんですが、その辺どうでしょうか。","respondent":"岩田まちづくり事業部長、片田建築課長、伊勢住環境整備担当課長","answer":"ですから、委員がおっしゃるように品川区全域６ｍに満たない道路に面したところの建物すべてが。したがいまして、これを超えるということがなかなか難しい。道路の拡幅の手法としまして、そこの拡幅する部分、区が買っていくという場合もありますし、戸越の場合は５０cm、４ｍ道路、中心から２ｍ。","id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"私道の場合もセットバック、４ｍで真ん中２ｍずつ下がりなさいと。確かに本当に当事者からすればつらいことだと思いますよね。今部長がおっしゃった、そう言われても、それぞれ皆さんの権利として土地というのは本当に今品川区の中で路線価も高いというのはわかります。それから、容積率も決まっちゃっている。そうすると、網がかかっていないところはどうしようもないということですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"その辺の入口的なところをもう少し全体のことを言っていただいたほうがいいのかなと思うんですけど。まさに、この１９番目の南品川三丁目の街なみ誘導型なんていうのは、今定例会中の議案でもありますし、地域の声を行政の皆さんと協力して進めて、議決が必要だというような、そういう全体、地区計画の今までやってきた手続も含めて、その辺のちょっと経緯を概要でいいですから、改めてお知らせを。","respondent":"岩田まちづくり事業部長","answer":"一番大きな地区は大崎駅周辺と東五反田地区、それから東品川地区、もちろん大井町周辺、ここら辺については、区が地域の中に入って意向調査を始め、地域の町会長や商店会長や、有力者の方にまちづくりの重要性を説明し、ずっとそういうことを積み重ねる中で。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私の知識不足だったかもしれないので、もう一回整理をして教えていただきたいんですが、用途地域の変更の件を教えてください。東京都の部分で、こういうことをしたいとか、こういうふうにまちの声もこうだったから、こういうふうに用途地域を変えたよということは、地区計画に至ってなければ変わらないという理解をしていたわけね。それで合っているのかどうか。そこら辺のところをちょっと教えてください。","respondent":"阿部都市計画課長","answer":"用途地域の変更の件ですけれども、従来は、東京都が全域一斉見直しという形でやられてきまして、それは平成１６年までです。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"私のやっぱり不勉強だったと思うんですが、地区計画が義務づけられたのね、これは。それは絶対条件の義務づけになっているから、そこまでいかないと、すべては変わりませんよという理解でいいのかだけ教えてください。","respondent":"阿部都市計画課長","answer":"ですから、地区計画、再開発等促進区は先ほど申し上げました都決定のものもありますけれども、基本的には地区計画、区決定が基本ですので、区のほうで地区計画を定める中で用途地域の変更も求められるところにつきましては、セットで都のほうに申請をしているという形になります。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすると、もう一点聞きたいんだけど、用途地域で決まった建ぺい率、容積率があるよね。だけど、地区計画の中で容積率の緩和だとかいろいろな形の３階建てまではこういう形で例えばいいですよとか、そういうものが出てきたときに、その地区計画だけで用途地域を変えなくたって、地区計画が優先されるなら、用途地域は放っておくという考えはだめなの。","respondent":"青木都市開発課長","answer":"若干補足しますけれども、先ほど都市計画課長からもご答弁申し上げました用途地域の見直しについては、今までは過去には東京都で言えば５年に１回ぐらい一斉に都内全体で見直しをかけていこう。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後にもう一個だけ。そうすると、品川区が地区計画をかけようという部分で、地域の人が盛り上がってきたら、例えばそれが１,０００m2では狭いのかなとか、どれぐらいという感覚というのはどこら辺に持てば、区民の人もまちの人でまちづくり協議会をつくろうといったときに、どれぐらいの感覚のところでみんな話し合って、こうまとまっていこうよという大体目安みたいなものはあるんですかね。","respondent":"青木都市開発課長","answer":"これも法律上は特に定めは、地区計画の面積はどれぐらいなきゃいけないという定めはないんですが、例えば東京都２３区は東京都が示している方針にほぼ従っておりまして、望ましい面積というのはちょっと今すぐお示しできないんですけれども、区分的にはある一定程度。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/900262?Template=document&Id=6356#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":28093,"voices":63}},{"id":"h19-20071205-5","meetingId":"h19-cm12","date":"2007年12月5日","dateIso":"2007-12-05","committee":"総務委員会","time":"午前１０時０２分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"を聴取してまいります。 施設入所者からの預かり金紛失","agenda":"を聴取してまいります。 施設入所者からの預かり金紛失","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"こういうことが起こったわけですから、全庁の中で、手提げ金庫等の中にある保管金の金額と、それから、預かり金の金額、根拠となる文書と実際の金がちゃんと整合性がとれているかということの確認はしたんでしょうかということを、まずお伺いしたいと思います。","respondent":"西島会計管理者","answer":"預かり金ですが、基本的にはつり銭が入っているということになっているんですが、預かり金等がある場合は、監査が年に１度、手提げ金庫の中身等も確認をしていると聞いております。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"こういうことが二度とないように、まず確認をしておきたいのが一つ。それから幾つかですけれども、まずは預かり金の管理の仕方といいましょうか、いわゆる公金管理のマニュアルに沿って対応していたんでしょうかということが一つ。そのときに、高齢福祉課の中で、このことについて、１２７万円が対象になっていると思われたんですが、４月以降どうなっていたんでしょうかお聞かせください。","respondent":"西島会計管理者","answer":"今回、所管に確認をしましたところ、都のほうでつくったマニュアルがございまして、先ほど、総務課長の説明にもありましたように、相続人がいない場合は、遺留金として、歳入歳出外現金として、雑部金として区のほうの大きな財布の中に入れるということになるんですが。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"ほかに二、三お伺いするので、後でまとめてお伺いしますけれども、それから、新聞報道なんですけれども、金庫は高齢福祉課職員しか開けられないと報道されていたんですけれども、これは事実であったんでしょうか。そうすると、当時、どのように調査を行ったのかということ。それから、もし、内部調査が順調に進んで事件が明らかになっていた場合、議会への対応はどうなるかということをお聞かせください。","respondent":"西島会計管理者、中川原広報広聴課長、榎本人事課長","answer":"１点目については、私のほうからお答えいたします。私のほうでは、朝日新聞とか、読売新聞とか、そういった記者は事前に呼びまして概要説明したんですけれども。内部調査で犯人がわかった場合については、厳正な処分ということで、地方公務員法上の処分をかけるという形で、内部調査を進めておりました。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、議会に対してどういうスタンスを持って、このことについてやるつもりだったんでしょうかということをお伺いしたかったので、そのことについて、改めてお願いします。それから、確認ですけれども、返還金は、既に遺族の方には支払ったんでしょうか。それから、当然、１００万円足りないわけですから、それはだれが負担をして支払ったんでしょうかということが一つ。","respondent":"桑村総務課長","answer":"現在、１００万円がないような状態ですけれども、これにつきましては、正直言いまして、いわゆる私人からの預かり金という性格で、もう一つ、先ほど会計管理者が申しましたけれども、歳入歳出外現金という形ではなくて、預かり金という現金で持っていたという性格がありまして。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"意見","question":"こういうところから、実はいろいろなマイナスが発生していて、広がっていって、こうなってしまったと思われますので、ぜひ、事故防止対策委員会は、このことについて十分協議してくださいとお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"というのが一つ。それから、先ほど言った、リリースをしたニュースに対して、先ほどのお話だと、広報広聴課にお伺いをされた方々よりも、どうも福祉高齢事業部長、高齢福祉課長、あるいは、総務課長のほうに問い合わせが行ったのかなと思われる節があるような妙なお答えだったけれども、それらに対する対応のあり方等も含めて、どうなっていたのかということ等を聞かせていただきたい、とりあえず。","respondent":"桑村総務課長、中川原広報広聴課長","answer":"先ほど、区長云々ということがございましたけれども、この公金の処理云々から検討するのが、正直言って、組織的対応をし出したのが１２月３日、いわゆる外部に出してから、私どもも自分のところの職員を使い。ただし問題によりましては、先ほどご指摘の立て替えの段につきましては、非常に微妙で、中でも議論が分れており、聞かれた人も非常に対応に苦慮し、ただし、うそは言ってはいけないという中で。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"それが１点。私はあれですから、あさってくださいという話になっちゃうよね。ですからその意味で、預かり金と称する、ちょっと全体としてはどう扱っていいかわからない、いわゆる公金というお金ではないらしいというものであっても、扱いはきちんと決めておくべきものなんだということなので、これをきちんとやっていただきたい。要するに、全く何もなければ、問題はないわけですから、何かがあったんです。","respondent":"桑村総務課長","answer":"１１月２２日のところでは、総務課も会計管理室も入らせていただいておりますけれども、もう１回何か調査ができないかということで、検討しています。これについてのご意見もよくわかりますので、こういった期間について、どう判断すべきか。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"もう一つ、その意味では、今、大変重要な範囲を含んでいると思いますけれども、気の弱い人が聞かれて違うことを言うと、もっと大変なことになっちゃうので、その意味ではきちんとやっていかなきゃいけないだろうと思いますし、またその中で、人事課の立場から言うと、職員を信じてあげなきゃならない部分もありますから、そこら辺との兼ね合いは大変難しいことではあろうと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の問題なんですけれども、私が感じたところ、細かいところは抜きにしまして、今回、こういう事件が起こって、事故防止対策委員会を立ち上げられて、これに類することについては、多分、これから防止というんでしょうか、起きないような体制をとられると思うんです。これは全体的な話です。ちょっと細かいところですけれども、この２点について答えていただければと思います。","respondent":"西島会計管理者、桑村総務課長、本間副区長","answer":"ただ、先ほどお話ししましたように、区の保管責任の中でのお金ということで、区費でできないかどうかということを、今、検討委員会の中で検討しているです。そういう意味では、手順書、それから職員の教育というのは、この事件だけじゃなくて、今後も必要ですし、また、この事件を受けて。そこで、先ほど、総務課長が説明したとおり、ただ、区長は公職の身にありますので。","id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"事件の経過は置いておいて、私がお話ししたかったのは、やはりこういう事故が起こったときに、マニュアルがあったのか、どうかということと、マニュアルどおり動いたのかどうかということが一つの重要なことだと思うんです。その部分を、ぜひとも強調したいと思います。そういうことが起きる前には、かなり庁舎内でも細かい、これはどうするんだ、あれはどうするんだということが起きていると思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"一つお聞きしたいのは、この中で、平成１９年９月に「当該入所者の関連書類が未処理であったため」と出されていますけれども、当該書類が未処理だったというのは、現金を預かったことは別としても、書類そのものが未処理であったという意味が、ちょっとよくわからないんです。ちょっとその２点。","respondent":"桑村総務課長","answer":"それからもう一つは、基本的には会計管理室と相談をして、金庫に入れるなら入れるような取り扱いする。それから、複数で金庫室に行くとか、そういった対応のものを、高齢福祉課のほうではつくっているものです。ただし、今現在は１件もございません。","id":"exchange-011"},{"speaker":"原委員","kind":"確認","question":"先ほどの中で、もう１回確認なんですけれども、手提げ金庫を所管の高齢福祉課が取りに行って、一応、封筒に入っているものであれば、これが何年間も入っているという認識のもとに行ったり来たりしていたのか。ということは、管理職以外の方が動いて、要するに手の届くところにあったのか、どうか。その辺のところを、ちょっとお聞かせいただけますでしょうか。","respondent":"桑村総務課長","answer":"おっしゃるとおり、その手提げ金庫の中に１２７万円余を入れていたです。そういう意味では、昼間は高齢福祉課の中にあったというのは事実です。平成１７年３月までは、半年間、そういう取り扱いをしたです。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"実際の問題としては、警察の調べが入ってくる。これは、最後に要望でお願いしたいんですけれども、これが事故なのか、事件なのか、言い方としては紛失なのか、窃盗なのか、横領なのか、この辺がはっきりしてこようかと思うんですけれども、これはちょっと意見として言うんですけれども、一生懸命やっている職員にとって非常に悲しい事件だと思いますので、この辺をしっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのは、当然、どの課にも手提げ金庫があるでしょう、その中で現金が毎日入っているでしょう。その金額については、今、その話があったように、監査で確認するけれども、何でわからなかったのかということと、ほかの課では、手提げ金庫の中の現金の確認はどうされていたのかということを、再度お聞かせください。お願いします。","respondent":"桑村総務課長","answer":"これは正しい処理なのかもしれませんけれども、何の金を持っているのか、あるいは、どう処理しているのかをもう１回確認させていただいて、なるべく事故が起こらない方法というのを検討させていただけばと考えています。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問・要望","question":"二つだけ。一つは、いろいろとマニュアルのお話がありましたけれども、マニュアルというスタイルで、この事例のときは、この事例のときはとマニュアルをいっぱいつくっちゃったら、何が何だかわからなくなっちゃうんですよ。だから、準用規定とかというのは非常に重要なことなんです、応用力の問題なんですから。やっぱり、区が１回預かれば、それは公金に準ずるものなんですよ、と思います。","respondent":"本間副区長","answer":"いずれにいたしましても、いろいろご指摘いただきましたが、現金そのものが非常に事故が起きやすいものだという意識をきちんと持って、できるだけ現金では保管しないという視点から、全庁的に、この委員会の中でもう一度見直しをしたいと考えておりますので。","id":"exchange-015"},{"speaker":"武内副委員長","kind":"質問・要望","question":"２点ほど教えていただきたいのが、一つは、最終的に、相続人が８人というふうに絞れたという、この８人と確定したのはいつごろなのかということが１点、もしわかれば。今後、もし、全員が使えるんだったら、場合によっては、一定のルールもまた決めなきゃいけないのかなとか、そういうふうにも思うんですけれども、その２点を教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"武内副委員長","kind":"確認","question":"詳しいことは所管じゃないのでわからないと思うんですけれども、もうちょっとその辺も、なぜスムーズにできなかったのかということが一つ疑問ですけれども、これはもう、お答えはいいと思うんです。そして、係長が責任を持って、その中の現金を確認してやるという形だと思うんです。１月以降のということは、ここで今聞いてもわかりませんので、それはまた別の機会に確認したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1770#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":29764,"voices":48}},{"id":"h19-20071226-9","meetingId":"h19-cm12","date":"2007年12月26日","dateIso":"2007-12-26","committee":"文教委員会","time":"午後１時０８分～午後１時３３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","topics":[{"id":"topic-01","title":"第９２号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第９２号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、最後に説明された対象者の数が３１名ということなんですけれども、そのほかに、品川区の公立幼稚園の職員の配置状況というのはどういうふうになっているのか、ちょっと教えていただきたいということが一つ。前例があったにしても、今回、なぜこのような事態になったと認識しておられるのか、その辺をちょっと伺いたいのが２点目です。ちょっとそこからで、あとで意見を述べます。","respondent":"市川庶務課長","answer":"今年も、先ほど申し上げたように、１１月上旬には、総務委員会と、こちらの幼稚園教諭の関係がありますので、文教委員会のほうに、人事委員会勧告の概要について説明をしています。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"職員の体制は、先ほどの説明以外に、公立幼稚園は６園だったかしら、記憶があれなので、全体の園長職が何人で、そのうち適用を受けるのが６人とか、もうちょっといると私は思っていたので、全体の職の状況をちょっと知りたいと思ったんです。これ以外にいないということであれば、今回のこの給与の改定を受ける適用対象はこれだけだけれども、ほかにどういう人がいるかということ。","respondent":"市川庶務課長","answer":"現在、幼稚園は９園ございまして、先ほど、園長６人と申し上げましたので、残りの３園の園長については、小学校長が兼ねております。それ以外の教諭については、先ほど、申し上げました数でこの条例の適用を受けているです。","id":"exchange-002"},{"speaker":"南委員","kind":"提案","question":"わかりました。そうでした、校長先生が兼ねていました、ありがとうございました。いろいろ資料を読んでみると、急遽、区長会のほうで、業務職給料表の改定、単独の提案を行ったということがあって、これが長引く原因になったというふうに承知しているんですけれども、そういう状況なのか、どうか、改めてちょっと確認をしたいと思います。","respondent":"市川庶務課長","answer":"先ほど、説明申し上げたように、例年と比べて今回の労使交渉が長引いた原因の一つは、今、委員がおっしゃられたように、本日、総務委員会の所管で、職員の給与に関する条例の中に規定しております、いわゆる業務職給料表の引き下げについて。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"１１月５日に報告をいただいて、そのときにも若干質問したと思うんですが、給料月額を減額ということは、退職金に関係してくるんじゃないかと思うんですが、どのぐらい変わっていくのかということ。それから、公立保育園の職員との開きというんですか、違いはあるんでしょうか。ある程度一定になっているのか、もしくは幼稚園教諭のほうが高い報酬という形になっているのか、その辺を教えていただきたい。","respondent":"市川庶務課長","answer":"今の給料体系は、若い人たちのところで差が出ていまして、ベテラン職になると、だんだんその差が縮まっていて、これはもう一般的な傾向ですが、ちなみに、初任給では、おおよそ１万円ぐらい差があります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"それに合わせた状況で、今回、下げたということなのか。将来において、どんどんまた月給が下がっていくと、結局、退職金がどんどん下がってしまうという形になりますので、そういうことだと、あまりよろしい状況ではないのかなと思うんですが、いかがでしょうか。","respondent":"市川庶務課長","answer":"今、ご質問いただいた点は、考え方は確かに２とおりに分れております。一つは、公務員給与は、民間準拠ということになっております。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"一つ目は、ここは文教委員会ですから幼稚園教育職員の部分なんですが、全体としては、３８円の公民格差が出ているということで、是正するほどではないということで、民間では、そういう報告が上がっていて、給与改定を見送るとなったわけですよね、(1)のところで。ですから、そういう点で、非常に問題がある状況だなと思わざるを得ないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"先ほども、質問をさせていただきましたが、やはりいろいろなところで、特に退職金等々に大きな影響が出てくるのではないかなというところ、これがひいては公務員給与というところにもかなり大きく影響が出てくる傾向がありますので、非常に危惧するところがあるなと思います。ただ、労使交渉のほうは既に終わられているというところにおいては、その中で出てきたことでありますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4622#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":6826,"voices":26}},{"id":"h19-20071226-5","meetingId":"h19-cm12","date":"2007年12月26日","dateIso":"2007-12-26","committee":"総務委員会","time":"午後１時０８分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"幾つかお尋ねしますけれども、ここまでずれ込んできた最大の要因なんですけれども、その辺をちょっと、もう少し詳しくお聞かせ願いたい。それから、平均９％給料削減がありますけれども、職種等の人数をちょっとお聞かせ願いたいと思います。","respondent":"榎本人事課長","answer":"その職種と人数ですけれども、業務職給料表の現在の適用人数が５４２人です。内訳は、今、手元に持って来なかったんですが、大体、清掃職が２００人ちょっと、用務と調理が百二、三十人というところがそれぞれで、残りが他の業務職という形です。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"最大の要因が倍率の差ということですけれども、人事院勧告で、最近は５０名規模の企業の給料を平均して公務員の給料がどうかという報告がされますけれども、そもそも、こういう業務系の職員の皆さんの国家公務員のところの基準というのは何かあるのかどうか、そこをお聞かせ願いたいんです。","respondent":"榎本人事課長","answer":"先ほど言った１.４倍とか１.５倍というのは、民間の賃金調査との倍率が、やはりそういうふうに出ておりまして、格差、均衡がとれていないのではないかということになっております。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"同様の職種の民間の給料というお話がありましたけれども、例えば給食調理なんかの業務で見ますと、民間で言えば、どちらかと言えば、今、パートなんかを使って仕事を進めるというところが多いかと思うんです。そことの比較で、給与水準が高いか、低いかというのを比べるということなんでしょうかね。ちょっとその辺を、もう少し細かく教えていただきたいんです。その辺もお聞かせ願います。","respondent":"榎本人事課長","answer":"その制度を、区の調理、用務系にも適用する中で、当然、技能主任は置けるような形になっているんですけれども、技能長につきましては、やはり２０人に１人という考え方がありまして、要は集団を束ねていく力の部分で技能長を置くという形がありまして、今現在。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"現実に、こういう削減によって、品川区のこうした職員の皆さんの生活が成り立っていくかどうかと、こういう聞き方もあれですけれども、どのように考えておられるのか、ちょっとそこもお聞きしたいと思います。","respondent":"榎本人事課長","answer":"行政サービスの部分ですけれども、やはりその辺がなかなか難しい問題ではありますけれども、職員から見た気持ちと、逆に区民のほうにこういう給料水準を公表した場合の気持ちの部分、両方の兼ね合いを考えますと、今の時点で、やはり各政令指定都市、それから。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"今、現給保障とおっしゃいましたけれども、実質的には、地域手当をアップして、基本給は下がるわけですよね。当然、退職金についても、例えば、先ほどの３４年以上の方は変わらないという話がありましたけれども、現実には基本給は下がるわけですから、退職金そのものも手取りとしては少なくなっていくということになるわけですよね。最後にそこだけ聞かせていただけますか。","respondent":"榎本人事課長","answer":"やはり、定年までなかなか上がりづらくなっているというもので、給与構造改革の一貫の中で、これまで、例えば５５歳で昇給停止になるものが、昇給停止にはしないで、少しでも上がるような形に切り替えたりとか、成績に応じた昇給加算というか、昇給区分が少し上がるような形とか。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問","question":"妥結をしたということで、この条例が上程されたということなんですけれども、その妥結の状況が、清掃労組については１１月２１日ということであり、そのほかの皆さんについては、１２月１４日ということだったというところで、交渉のレベル等の関係で、若干の違いがあったやに聞いているわけですけれども、それが条例という形になるんですから、結局、同じ扱いをするという形ですよね。","respondent":"榎本人事課長","answer":"それ以外の違いにつきましては、先ほどちょっと話がありましたが、技能長の設置について、各区が検討する、要は、清掃以外の部分についても技能長を設置できないかを検討していくということで、この部分の提案がありまして、その部分で妥結をしたということで、それを含めて。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"今のところ、２３区が統一交渉的に行われているわけですけれども、今後どうなるかという部分を含めると、それぞれの、品川区は品川区の職員の皆さんとどう交渉していくのかということが起こるのか、起こらないのかというふうな見通し等は、どうお考えですか。","respondent":"榎本人事課長","answer":"条例自体は統一ですけれども、細かい、例えば２３区の中での給与格付の昇任率ですとか、その部分につきましては各区でそれぞれ定めておりますので、その中については、まだ細かい詰めが残っているというものです。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"改めて何点か質問させていただきたいんですが、まず、条例を改正する理由、つまり、今なぜ職員の給与を下げるかという理由づけを、もう一度ご説明していただきたい。新しく採用された職員にそれを適用するということでいいでしょうかということ。それを、まずお答えください。","respondent":"榎本人事課長","answer":"現給保障の部分ですけれども、もし新規採用がいれば、新しい給料表ですけれども、基本的には、技能系の職種につきましては、新規採用を控えている区がほとんどですので、現給保障の部分で推移するだろうと見込んでおります。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"下げる理由についてはわかるところもあるんですけれども、そのことについては、随分前から言われていたことではありますよね。ですから、何で今、これが出てきたのかなと。これが１点目です。確認ですけれども、つまり、新規職員が採用された場合には、下がった条例が適用になるけれども、今までの職員の場合には、現給保障、つまり今の給料のままでいくということでよろしいんですか。それの確認。","respondent":"榎本人事課長","answer":"説明が、行政職給料表（一）、（二）という言い方になっていますので、かなり複雑にはなるんですけれども、実際にそれぞれ役割を持った仕事もしておりますので、そういったものも含めながら、そういうふうに地域の基準に合わせた形の説明をしていきたいと考えております。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"もう一度確認で、現給保障についてなんですけれども、今のご説明ですと、５年間で約１０億円下がってくるということですから、つまり、本来の給与の上げ幅があって、それを見直すことによって、その上げ幅が下がる。結果として、５年間で給与が下がっていくという考え方でよろしいんでしょうかという確認だけ。その現給保障のところだけ、ご説明をお願いします。","respondent":"榎本人事課長","answer":"そうすると、現給保障で、このラインで引いたときに、将来、前の給料表ですと上がる部分が、ずっと先まで上がらないという形になりますので、この上がるべきものが、少なくとも５年間で約１０億円という数値が出てくるというものです。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうから２点ございまして、時期が１月と４月になっているんですが、ここをちょっとご説明いただきたい。それから、もう少し細かくなるんですが、平成２０年度は経過措置の中で２分の１ということですが、実際に該当する人数がわかればお教えいただきたいと思います。","respondent":"榎本人事課長","answer":"１月、４月の実施時期の違いですけれども、給与勧告については速やかに実施という形になりますので、１月１日という形で、特別区人事委員会の勧告の中で指摘された時期になっております。","id":"exchange-011"},{"speaker":"原委員","kind":"確認","question":"再度確認なんですけれども、不利益をこうむる退職職員はいないだろうという基本的な考え方でよろしいんですか。","respondent":"榎本人事課長","answer":"この退職手当の支給率に伴っての部分は、出てこないというものです。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1772#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":12117,"voices":38}}]);
